func findSpecByLong(long string) *argSpec {
	for _, s := range argSpecs {
		if s.long == long {
			return s
		}
	}
	return nil
}

func findSpecByShort(c byte) *argSpec {
	for _, s := range argSpecs {
		if s.short != 0 && s.short == c {
			return s
		}
	}
	return nil
}

func findSpecByID(id string) *argSpec {
	for _, s := range argSpecs {
		if s.id == id {
			return s
		}
	}
	return nil
}

// cliError is a clap-style usage error (exit code 2).
type cliError struct {
	msg string
}

func (e *cliError) Error() string { return e.msg }

// parsedArgs holds the raw results of parsing.
type parsedArgs struct {
	values   map[string][]string // id -> values (flags get "true")
	present  map[string]bool
	order    []string // ids in command line order (first occurrence)
	path     string
	hasPath  bool
	binName  string
	fromEnv  map[string]bool
	showHelp int // 0 none, 1 short, 2 long
	showVer  bool
}

func usageDefault(bin string) string {
	return "Usage: " + bin + " [OPTIONS] [PATH]"
}

func moreInfo() string {
	return "For more information, try '--help'."
}

// buildUsage builds the "smart" usage line used by clap for some errors.
func (p *parsedArgs) buildUsage(exclude map[string]bool, extraFirst []string) string {
	var parts []string
	seen := map[string]bool{}
	add := func(id string) {
		if seen[id] || exclude[id] {
			return
		}
		s := findSpecByID(id)
		if s == nil {
			return
		}
		seen[id] = true
		parts = append(parts, s.displayName())
	}
	// required-by-present arguments (clap's "required" graph) first
	var required []string
	reqSeen := map[string]bool{}
	for _, id := range p.order {
		if exclude[id] {
			continue
		}
		s := findSpecByID(id)
		for _, r := range s.requires {
			if !reqSeen[r] {
				reqSeen[r] = true
				required = append(required, r)
			}
		}
	}
	for _, id := range extraFirst {
		if !reqSeen[id] {
			reqSeen[id] = true
			required = append(required, id)
		}
	}
	for _, r := range required {
		// unroll the requirements of the required arg itself
		for _, rr := range unrollRequires(r) {
			add(rr)
		}
		add(r)
	}
	for _, id := range p.order {
		add(id)
	}
	pathPart := "[PATH]"
	if p.hasPath {
		pathPart = "<PATH>"
	}
	if len(parts) == 0 {
		return "Usage: " + p.binName + " [OPTIONS] " + pathPart
	}
	return "Usage: " + p.binName + " " + strings.Join(parts, " ") + " " + pathPart
}

func unrollRequires(id string) []string {
	var out []string
	processed := map[string]bool{}
	stack := []string{id}
	for len(stack) > 0 {
		a := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if processed[a] {
			continue
		}
		processed[a] = true
		s := findSpecByID(a)
		if s == nil {
			continue
		}
		for _, r := range s.requires {
			rs := findSpecByID(r)
			if rs != nil && len(rs.requires) > 0 {
				stack = append(stack, r)
			}
			out = append(out, r)
		}
	}
	return out
}

// jaro computes the Jaro similarity used by clap for suggestions.
func jaro(a, b string) float64 {
	ra := []rune(a)
	rb := []rune(b)
	if len(ra) == 0 && len(rb) == 0 {
		return 1
	}
	if len(ra) == 0 || len(rb) == 0 {
		return 0
	}
	searchRange := max(len(ra), len(rb))/2 - 1
	if searchRange < 0 {
		searchRange = 0
	}
	matchedB := make([]bool, len(rb))
	var matches, transpositions int
	var matchedA []int
	for i, ca := range ra {
		lo := i - searchRange
		if lo < 0 {
			lo = 0
		}
		hi := i + searchRange
		if hi >= len(rb) {
			hi = len(rb) - 1
		}
		for j := lo; j <= hi; j++ {
			if !matchedB[j] && rb[j] == ca {
				matchedB[j] = true
				matches++
				matchedA = append(matchedA, j)
				break
			}
		}
	}
	if matches == 0 {
		return 0
	}
	// count transpositions
	k := 0
	for i, ca := range ra {
		_ = i
		found := false
		for _, j := range matchedA {
			_ = j
			break
		}
		_ = found
		_ = ca
	}
	// simpler: build matched sequences
	var seqA []rune
	for i, ca := range ra {
		lo := i - searchRange
		if lo < 0 {
			lo = 0
		}
		_ = lo
		_ = ca
	}
	// recompute properly
	matchedB = make([]bool, len(rb))
	matchedAFlags := make([]bool, len(ra))
	for i, ca := range ra {
		lo := i - searchRange
		if lo < 0 {
			lo = 0
		}
		hi := i + searchRange
		if hi >= len(rb) {
			hi = len(rb) - 1
		}
		for j := lo; j <= hi; j++ {
			if !matchedB[j] && rb[j] == ca {
				matchedB[j] = true
				matchedAFlags[i] = true
				break
			}
		}
	}
	for i := range ra {
		if matchedAFlags[i] {
			seqA = append(seqA, ra[i])
		}
	}
	var seqB []rune
	for j := range rb {
		if matchedB[j] {
			seqB = append(seqB, rb[j])
		}
	}
	for i := range seqA {
		if i < len(seqB) && seqA[i] != seqB[i] {
			transpositions++
		}
	}
	_ = k
	m := float64(matches)
	t := float64(transpositions) / 2
	return (m/float64(len(ra)) + m/float64(len(rb)) + (m-t)/m) / 3
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// didYouMean returns candidate strings similar to v (clap uses jaro > 0.7... actually
// confidence threshold 0.7 with jaro-winkler in older versions; jaro in clap 4).
func didYouMean(v string, candidates []string) []string {
	type cand struct {
		s    string
		conf float64
	}
	var out []cand
	for _, c := range candidates {
		conf := jaro(v, c)
		if conf > 0.7 {
			out = append(out, cand{c, conf})
		}
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].conf > out[j].conf })
	var res []string
	for _, c := range out {
		res = append(res, c.s)
	}
	return res
}

func isNegativeNumber(s string) bool {
	if len(s) < 2 || s[0] != '-' {
		return false
	}
	_, err := strconv.ParseFloat(s, 64)
	return err == nil
}

// parseArgs parses the command line in a clap-compatible manner.
func parseArgs(bin string, args []string) (*parsedArgs, error) {
	p := &parsedArgs{values: map[string][]string{}, present: map[string]bool{}, binName: bin, fromEnv: map[string]bool{}}
	errMultiple := func(s *argSpec) error {
		return &cliError{fmt.Sprintf("error: the argument '%s' cannot be used multiple times\n\n%s\n\n%s\n", s.displayName(), usageDefault(bin), moreInfo())}
	}
	setValue := func(s *argSpec, v string) error {
		if p.present[s.id] && !s.multiple {
			return errMultiple(s)
		}
		if !p.present[s.id] {
			p.order = append(p.order, s.id)
		}
		p.present[s.id] = true
		p.values[s.id] = append(p.values[s.id], v)
		return nil
	}
	errUnexpected := func(arg string) error {
		var sb strings.Builder
		sb.WriteString(fmt.Sprintf("error: unexpected argument '%s' found\n\n", arg))
		if strings.HasPrefix(arg, "--") && len(arg) > 2 {
			name := arg[2:]
			if i := strings.IndexByte(name, '='); i >= 0 {
				name = name[:i]
			}
			var cands []string
			for _, s := range argSpecs {
				cands = append(cands, s.long)
			}
			cands = append(cands, "help", "version")
			sugg := didYouMean(name, cands)
			if len(sugg) > 0 {
				sb.WriteString(fmt.Sprintf("  tip: a similar argument exists: '--%s'\n\n", sugg[0]))
				sp := findSpecByLong(sugg[0])
				if sp != nil {
					sb.WriteString(p.buildUsage(nil, []string{sp.id}) + "\n\n")
				} else {
					sb.WriteString(usageDefault(bin) + "\n\n")
				}
				sb.WriteString(moreInfo() + "\n")
				return &cliError{sb.String()}
			}
		}
		if strings.HasPrefix(arg, "-") {
			sb.WriteString(fmt.Sprintf("  tip: to pass '%s' as a value, use '-- %s'\n\n", arg, arg))
		}
		sb.WriteString(usageDefault(bin) + "\n\n" + moreInfo() + "\n")
		return &cliError{sb.String()}
	}
	errNoValue := func(s *argSpec) error {
		return &cliError{fmt.Sprintf("error: a value is required for '%s' but none was supplied\n\n%s\n", s.displayName(), moreInfo())}
	}
	looksLikeFlag := func(s string) bool {
		if s == "-" {
			return false
		}
		if strings.HasPrefix(s, "--") {
			return true
		}
		if strings.HasPrefix(s, "-") && len(s) > 1 {
			return !isNegativeNumber(s) || true
		}
		return false
	}
	i := 0
	dashdash := false
	for i < len(args) {
		arg := args[i]
		i++
		if dashdash {
			if p.hasPath {
				return nil, errUnexpected(arg)
			}
			p.path = arg
			p.hasPath = true
			continue
		}
		if arg == "--" {
			dashdash = true
			continue
		}
		if strings.HasPrefix(arg, "--") {
			name := arg[2:]
			var val *string
			if eq := strings.IndexByte(name, '='); eq >= 0 {
				v := name[eq+1:]
				val = &v
				name = name[:eq]
			}
			if name == "help" {
				p.showHelp = 2
				return p, nil
			}
			if name == "version" {
				p.showVer = true
				return p, nil
			}
			s := findSpecByLong(name)
			if s == nil {
				return nil, errUnexpected(arg)
			}
			switch s.kind {
			case kindFlag:
				if val != nil {
					if p.present[s.id] {
						return nil, errMultiple(s)
					}
					return nil, &cliError{fmt.Sprintf("error: unexpected value '%s' for '%s' found; no more were expected\n\n%s\n\n%s\n", *val, s.displayName(), p.buildUsage(nil, []string{s.id}), moreInfo())}
				}
				if err := setValue(s, "true"); err != nil {
					return nil, err
				}
			case kindValue:
				if val != nil {
					if err := setValue(s, *val); err != nil {
						return nil, err
					}
				} else {
					if i >= len(args) || looksLikeFlag(args[i]) {
						if p.present[s.id] && !s.multiple {
							return nil, errMultiple(s)
						}
						return nil, errNoValue(s)
					}
					if err := setValue(s, args[i]); err != nil {
						return nil, err
					}
					i++
				}
			case kindOptValue:
				if val != nil {
					if *val == "" {
						return nil, errNoValue(s)
					}
					if err := setValue(s, *val); err != nil {
						return nil, err
					}
				} else if i < len(args) && !looksLikeFlag(args[i]) {
					if err := setValue(s, args[i]); err != nil {
						return nil, err
					}
					i++
				} else {
					if err := setValue(s, ""); err != nil {
						return nil, err
					}
				}
			}
			continue
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// short flag cluster
			j := 1
			for j < len(arg) {
				c := arg[j]
				j++
				if c == 'h' {
					p.showHelp = 1
					return p, nil
				}
				if c == 'V' {
					p.showVer = true
					return p, nil
				}
				s := findSpecByShort(c)
				if s == nil {
					return nil, errUnexpected("-" + string(c))
				}
				switch s.kind {
				case kindFlag:
					if err := setValue(s, "true"); err != nil {
						return nil, err
					}
				case kindValue:
					rest := arg[j:]
					if strings.HasPrefix(rest, "=") {
						rest = rest[1:]
						if err := setValue(s, rest); err != nil {
							return nil, err
						}
						j = len(arg)
					} else if rest != "" {
						if err := setValue(s, rest); err != nil {
							return nil, err
						}
						j = len(arg)
					} else {
						if i >= len(args) || looksLikeFlag(args[i]) {
							if p.present[s.id] && !s.multiple {
								return nil, errMultiple(s)
							}
							return nil, errNoValue(s)
						}
						if err := setValue(s, args[i]); err != nil {
							return nil, err
						}
						i++
					}
				case kindOptValue:
					rest := arg[j:]
					if strings.HasPrefix(rest, "=") {
						rest = rest[1:]
						if rest == "" {
							return nil, errNoValue(s)
						}
						if err := setValue(s, rest); err != nil {
							return nil, err
						}
						j = len(arg)
					} else if rest != "" {
						if err := setValue(s, rest); err != nil {
							return nil, err
						}
						j = len(arg)
					} else if i < len(args) && !looksLikeFlag(args[i]) {
						if err := setValue(s, args[i]); err != nil {
							return nil, err
						}
						i++
					} else {
						if err := setValue(s, ""); err != nil {
							return nil, err
						}
					}
				}
			}
			continue
		}
		// positional
		if p.hasPath {
			return nil, errUnexpected(arg)
		}
		p.path = arg
		p.hasPath = true
	}
	return p, nil
}

// applyEnv fills in values from environment variables for absent arguments.
func (p *parsedArgs) applyEnv() error {
	for _, s := range argSpecs {
		if s.env == "" || p.present[s.id] {
			continue
		}
		v, ok := os.LookupEnv(s.env)
		if !ok {
			continue
		}
		switch s.kind {
		case kindFlag:
			if v == "" {
				return &cliError{fmt.Sprintf("error: a value is required for '%s' but none was supplied\n  [possible values: true, false]\n\n%s\n", s.displayName(), moreInfo())}
			}
			if v != "true" && v != "false" {
				return &cliError{fmt.Sprintf("error: invalid value '%s' for '%s'\n  [possible values: true, false]\n\n%s\n", v, s.displayName(), moreInfo())}
			}
			if v == "true" {
				p.values[s.id] = []string{"true"}
				p.present[s.id] = true
				p.fromEnv[s.id] = true
			}
		default:
			p.values[s.id] = []string{v}
			p.present[s.id] = true
			p.fromEnv[s.id] = true
		}
	}
	if !p.hasPath {
		if v, ok := os.LookupEnv("MINISERVE_PATH"); ok {
			p.path = v
			p.hasPath = true
		}
	}
	return nil
}

func (p *parsedArgs) errInvalidValue(s *argSpec, v, reason string) error {
	return &cliError{fmt.Sprintf("error: invalid value '%s' for '%s': %s\n\n%s\n", v, s.displayName(), reason, moreInfo())}
}

func (p *parsedArgs) errPossible(s *argSpec, v string) error {
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("error: invalid value '%s' for '%s'\n  [possible values: %s]\n", v, s.displayName(), strings.Join(s.possible, ", ")))
	sugg := didYouMean(v, s.possible)
	if len(sugg) > 0 {
		sb.WriteString(fmt.Sprintf("  tip: a similar value exists: '%s'\n", sugg[0]))
	}
	sb.WriteString("\n" + moreInfo() + "\n")
	return &cliError{sb.String()}
}

// validate checks possible values, requires and conflicts and converts values.
func (p *parsedArgs) validate() error {
	// possible values
	for _, s := range argSpecs {
		if !p.present[s.id] || len(s.possible) == 0 {
			continue
		}
		for idx, v := range p.values[s.id] {
			ok := false
			for _, pv := range s.possible {
				if pv == v || (s.ignoreCase && strings.EqualFold(pv, v)) {
					ok = true
					p.values[s.id][idx] = pv
					break
				}
			}
			if !ok {
				return p.errPossible(s, v)
			}
		}
	}
	// typed values
	if p.present["port"] {
		v := p.values["port"][0]
		if err := checkU16(v); err != "" {
			return p.errInvalidValue(findSpecByID("port"), v, err)
		}
	}
	if p.present["web_upload_concurrency"] {
		v := p.values["web_upload_concurrency"][0]
		if err := checkUsize(v); err != "" {
			return p.errInvalidValue(findSpecByID("web_upload_concurrency"), v, err)
		}
	}
	if p.present["chmod"] {
		v := p.values["chmod"][0]
		if _, err := strconv.ParseUint(v, 8, 32); err != nil {
			return p.errInvalidValue(findSpecByID("chmod"), v, rustIntErr(v, err, 8))
		}
	}
	if p.present["interfaces"] {
		for _, v := range p.values["interfaces"] {
			if net.ParseIP(v) == nil || strings.Contains(v, "%") {
				return p.errInvalidValue(findSpecByID("interfaces"), v, "invalid IP address syntax")
			}
		}
	}
	if p.present["auth"] {
		for _, v := range p.values["auth"] {
			if _, err := parseAuth(v); err != nil {
				return p.errInvalidValue(findSpecByID("auth"), v, err.Error())
			}
		}
	}
	if p.present["header"] {
		for _, v := range p.values["header"] {
			if _, _, err := parseHeaderArg(v); err != nil {
				return p.errInvalidValue(findSpecByID("header"), v, err.Error())
			}
		}
	}
	// conflicts
	for _, id := range p.order {
		s := findSpecByID(id)
		for _, c := range s.conflicts {
			if p.present[c] && !p.fromEnv[c] {
				cs := findSpecByID(c)
				// clap reports the first-seen argument as the one that conflicts
				first, second := s, cs
				for _, o := range p.order {
					if o == s.id {
						first, second = s, cs
						break
					}
					if o == cs.id {
						first, second = cs, s
						break
					}
				}
				exclude := map[string]bool{second.id: true}
				return &cliError{fmt.Sprintf("error: the argument '%s' cannot be used with '%s'\n\n%s\n\n%s\n", first.displayName(), second.displayName(), p.buildUsage(exclude, nil), moreInfo())}
			}
		}
	}
	// requires
	var missing []string
	seen := map[string]bool{}
	for _, id := range p.order {
		s := findSpecByID(id)
		for _, r := range s.requires {
			if !p.present[r] && !seen[r] {
				seen[r] = true
				missing = append(missing, r)
			}
		}
	}
	if len(missing) > 0 {
		var sb strings.Builder
		sb.WriteString("error: the following required arguments were not provided:\n")
		for _, m := range missing {
			sb.WriteString("  " + findSpecByID(m).displayName() + "\n")
		}
		sb.WriteString("\n" + p.buildUsage(nil, nil) + "\n\n" + moreInfo() + "\n")
		return &cliError{sb.String()}
	}
	return nil
}

func rustIntErr(v string, err error, base int) string {
	if v == "" {
		return "cannot parse integer from empty string"
	}
	s := v
	if strings.HasPrefix(s, "+") || strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	if s == "" {
		return "invalid digit found in string"
	}
	for _, c := range s {
		d := -1
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'z':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'Z':
			d = int(c-'A') + 10
		}
		if d < 0 || d >= base {
			return "invalid digit found in string"
		}
	}
	if strings.HasPrefix(v, "-") {
		return "invalid digit found in string"
	}
	return "number too large to fit in target type"
}

func checkU16(v string) string {
	if v == "" {
		return "cannot parse integer from empty string"
	}
	n, err := strconv.ParseInt(v, 10, 64)
	if err != nil {
		if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange {
			return fmt.Sprintf("%s is not in 0..=65535", v)
		}
		return rustIntErr(v, err, 10)
	}
	if n < 0 || n > 65535 {
		return fmt.Sprintf("%s is not in 0..=65535", v)
	}
	return ""
}

func checkUsize(v string) string {
	if v == "" {
		return "cannot parse integer from empty string"
	}
	_, err := strconv.ParseUint(v, 10, 64)
	if err != nil {
		if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange {
			return "number too large to fit in target type"
		}
		return rustIntErr(v, err, 10)
	}
	return ""
}

// authEntry is a required username/password combination.
type authEntry struct {
	username string
	password []byte // raw password or hash bytes
	hashType string // "", "sha256", "sha512"
}

func parseAuth(s string) (authEntry, error) {
	parts := strings.SplitN(s, ":", 3)
	if len(parts) < 2 {
		return authEntry{}, fmt.Errorf("Invalid format for credentials string. Expected username:password, username:sha256:hash or username:sha512:hash")
	}
	username := parts[0]
	if len(parts) == 3 {
		hashType := parts[1]
		hashHex := parts[2]
		switch hashType {
		case "sha256", "sha512":
			b, err := hex.DecodeString(hashHex)
			if err != nil {
				return authEntry{}, fmt.Errorf("Invalid format for password hash. Expected hex code")
			}
			return authEntry{username: username, password: b, hashType: hashType}, nil
		default:
			return authEntry{}, fmt.Errorf("Invalid format for password hash. Expected hex code")
		}
	}
	return authEntry{username: username, password: []byte(parts[1])}, nil
}

func (a *authEntry) matches(user, pass string) bool {
	if a.username != user {
		return false
	}
	switch a.hashType {
	case "sha256":
		h := sha256.Sum256([]byte(pass))
		return string(h[:]) == string(a.password)
	case "sha512":
		h := sha512.Sum512([]byte(pass))
		return string(h[:]) == string(a.password)
	default:
		return string(a.password) == pass
	}
}

func isTokenChar(c byte) bool {
	if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' {
		return true
	}
	return strings.IndexByte("!#$%&'*+-.^_`|~", c) >= 0
}

func parseHeaderArg(s string) (string, string, error) {
	i := strings.IndexByte(s, ':')
	if i < 0 {
		return "", "", fmt.Errorf("invalid header name")
	}
	name := s[:i]
	value := strings.TrimSpace(s[i+1:])
	if name == "" {
		return "", "", fmt.Errorf("invalid header name")
	}
	for k := 0; k < len(name); k++ {
		if !isTokenChar(name[k]) {
			return "", "", fmt.Errorf("invalid header name")
		}
	}
	for k := 0; k < len(value); k++ {
		c := value[k]
		if c < 32 && c != '\t' || c == 127 {
			return "", "", fmt.Errorf("failed to parse header value")
		}
	}
	return strings.ToLower(name), value, nil
}
