}

func logInfo(msg string) {
	if !verboseLogging {
		return
	}
	logMu.Lock()
	defer logMu.Unlock()
	fmt.Fprintf(os.Stdout, "%s [INFO] %s\n", logTimestamp(), msg)
}

func logWarn(msg string) {
	logMu.Lock()
	defer logMu.Unlock()
	fmt.Fprintf(os.Stderr, "%s [WARN] %s\n", logTimestamp(), msg)
}

func logError(msg string) {
	logMu.Lock()
	defer logMu.Unlock()
	fmt.Fprintf(os.Stderr, "%s [ERROR] %s\n", logTimestamp(), msg)
}

// logErrorChain logs each line of a multi-line error description separately.
func logErrorChain(desc string) {
	for _, line := range strings.Split(desc, "\n") {
		logError(line)
	}
}

func isTerminal(f *os.File) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(syscall.TCGETS), uintptr(unsafePointer(&termios)))
	return errno == 0
}

var errnoNames = map[syscall.Errno]string{
	syscall.EPERM:        "Operation not permitted",
	syscall.ENOENT:       "No such file or directory",
	syscall.EIO:          "Input/output error",
	syscall.EBADF:        "Bad file descriptor",
	syscall.EACCES:       "Permission denied",
	syscall.EEXIST:       "File exists",
	syscall.EXDEV:        "Invalid cross-device link",
	syscall.ENOTDIR:      "Not a directory",
	syscall.EISDIR:       "Is a directory",
	syscall.EINVAL:       "Invalid argument",
	syscall.EFBIG:        "File too large",
	syscall.ENOSPC:       "No space left on device",
	syscall.EROFS:        "Read-only file system",
	syscall.EMLINK:       "Too many links",
	syscall.ENAMETOOLONG: "File name too long",
	syscall.ENOTEMPTY:    "Directory not empty",
	syscall.ELOOP:        "Too many levels of symbolic links",
	syscall.EADDRINUSE:   "Address already in use",
	syscall.EADDRNOTAVAIL: "Cannot assign requested address",
	syscall.ECONNREFUSED: "Connection refused",
	syscall.ETXTBSY:      "Text file busy",
	syscall.EBUSY:        "Device or resource busy",
	syscall.ENOTSUP:      "Operation not supported",
	syscall.EMFILE:       "Too many open files",
	syscall.EPIPE:        "Broken pipe",
	syscall.ECONNRESET:   "Connection reset by peer",
}

// rustIoError formats an error like Rust's std::io::Error Display.
func rustIoError(err error) string {
	if err == nil {
		return ""
	}
	if en, ok := err.(syscall.Errno); ok {
		name, ok := errnoNames[en]
		if !ok {
			name = en.Error()
			if len(name) > 0 {
				name = strings.ToUpper(name[:1]) + name[1:]
			}
		}
		return fmt.Sprintf("%s (os error %d)", name, int(en))
	}
	return err.Error()
}
