	Proto      string
	Header     textproto.MIMEHeader
	Body       io.Reader
	RemoteAddr string
	RemoteIP   string
	TLS        bool
	conn       *httpConn
	bodyLen    int64 // -1 unknown
	expect100  bool
	sent100    bool
