// Handler processes requests.
type Handler func(req *Request) *Response

type httpConn struct {
	conn net.Conn
	br   *bufio.Reader
	bw   *bufio.Writer
}

// HTTPServer is a tiny HTTP/1.1 server.
type HTTPServer struct {
	Handler  Handler
	TLSConf  *tls.Config
	wg       sync.WaitGroup
	AfterReq func(req *Request, resp *Response, written int64, dur time.Duration)
}

func (s *HTTPServer) Serve(ln net.Listener) error {
	if s.TLSConf != nil {
		ln = tls.NewListener(ln, s.TLSConf)
	}
	for {
		c, err := ln.Accept()
		if err != nil {
