func (s *HTTPServer) serveConn(c net.Conn) {
	defer c.Close()
	hc := &httpConn{conn: c, br: bufio.NewReaderSize(c, 64*1024), bw: bufio.NewWriterSize(c, 64*1024)}
	_, isTLS := c.(*tls.Conn)
	for {
		c.SetReadDeadline(time.Now().Add(5 * time.Second))
