		hdr, err := tp.ReadMIMEHeader()
		if err != nil {
			hc.writeSimple(400, "Bad Request", true)
			return
		}
		req.Header = hdr
		target := req.Target
		if strings.HasPrefix(target, "http://") || strings.HasPrefix(target, "https://") {
			// absolute-form: strip scheme and authority
			rest := target[strings.Index(target, "://")+3:]
			if i := strings.IndexByte(rest, '/'); i >= 0 {
				target = rest[i:]
			} else {
				target = "/"
			}
		}
		if i := strings.IndexByte(target, '?'); i >= 0 {
			req.RawPath = target[:i]
			req.RawQuery = target[i+1:]
		} else {
			req.RawPath = target
		}
		if i := strings.IndexByte(req.RawPath, '#'); i >= 0 {
			req.RawPath = req.RawPath[:i]
		}
