		req.bodyLen = 0
		closeAfter := false
		connHdr := strings.ToLower(hdr.Get("Connection"))
		if req.Proto == "HTTP/1.0" {
			closeAfter = !strings.Contains(connHdr, "keep-alive")
		} else if strings.Contains(connHdr, "close") {
			closeAfter = true
		}
		if strings.EqualFold(hdr.Get("Expect"), "100-continue") {
			req.expect100 = true
		}
		var body io.Reader = strings.NewReader("")
		if te := hdr.Get("Transfer-Encoding"); te != "" {
			if strings.EqualFold(te, "chunked") {
				body = httputil.NewChunkedReader(hc.br)
				req.bodyLen = -1
			} else {
				hc.writeSimple(501, "Not Implemented", true)
				return
			}
		} else if cl := hdr.Get("Content-Length"); cl != "" {
			n, err := strconv.ParseInt(strings.TrimSpace(cl), 10, 64)
			if err != nil || n < 0 {
				hc.writeSimple(400, "Bad Request", true)
				return
			}
			req.bodyLen = n
			body = io.LimitReader(hc.br, n)
		}
		req.Body = &bodyReader{r: body, req: req}

		start := time.Now()
		resp := s.Handler(req)
		if resp == nil {
			resp = newResponse(500)
		}
		// drain remaining body (up to a limit) so the connection can be reused
		if !closeAfter {
			if req.expect100 && !req.sent100 {
				// body never requested; client hasn't sent it. Fine.
			} else {
				n, _ := io.CopyN(io.Discard, req.Body, 1<<20)
				if n == 1<<20 {
					// too much left, give up on keep-alive
					closeAfter = true
				}
			}
		}
		written, werr := hc.writeResponse(req, resp, closeAfter)
		if s.AfterReq != nil {
			s.AfterReq(req, resp, written, time.Since(start))
		}
		if werr != nil || closeAfter {
			return
		}
	}
