type bodyReader struct {
	r   io.Reader
	req *Request
}

func (b *bodyReader) Read(p []byte) (int, error) {
	if b.req.expect100 && !b.req.sent100 {
		b.req.sent100 = true
		b.req.conn.bw.WriteString("HTTP/1.1 100 Continue\r\n\r\n")
		b.req.conn.bw.Flush()
	}
	return b.r.Read(p)
}

func (hc *httpConn) writeSimple(status int, reason string, closeConn bool) {
	fmt.Fprintf(hc.bw, "HTTP/1.1 %d %s\r\ncontent-length: 0\r\nconnection: close\r\ndate: %s\r\n\r\n", status, reason, httpDate(time.Now()))
	hc.bw.Flush()
}

func httpDate(t time.Time) string {
	return t.UTC().Format("Mon, 02 Jan 2006 15:04:05") + " GMT"
}

func statusText(code int) string {
	if code == 207 {
		return "Multi-Status"
	}
	t := http.StatusText(code)
	if t == "" {
		return "Unknown"
	}
	return t
}

type countWriter struct {
	w io.Writer
	n int64
}

func (c *countWriter) Write(p []byte) (int, error) {
	n, err := c.w.Write(p)
	c.n += int64(n)
	return n, err
}

func (hc *httpConn) writeResponse(req *Request, resp *Response, closeAfter bool) (int64, error) {
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("HTTP/1.1 %d %s\r\n", resp.Status, statusText(resp.Status)))
	isHead := req.Method == "HEAD"
	noBody := resp.Status == 304 || resp.Status == 204 || (resp.Status >= 100 && resp.Status < 200)
	chunked := false
	if resp.Stream != nil {
		if req.Proto == "HTTP/1.0" {
			closeAfter = true
		} else {
			chunked = true
			sb.WriteString("transfer-encoding: chunked\r\n")
		}
	} else if !noBody {
		if !(len(resp.Body) == 0 && resp.NoContentLength) {
			sb.WriteString(fmt.Sprintf("content-length: %d\r\n", len(resp.Body)))
		}
	}
	for _, h := range resp.Headers {
		sb.WriteString(h.name)
		sb.WriteString(": ")
		sb.WriteString(h.value)
		sb.WriteString("\r\n")
	}
	if closeAfter {
		sb.WriteString("connection: close\r\n")
	}
	sb.WriteString("date: " + httpDate(time.Now()) + "\r\n\r\n")
	if _, err := hc.bw.WriteString(sb.String()); err != nil {
		return 0, err
	}
	var written int64
	if isHead || noBody {
		return written, hc.bw.Flush()
	}
	if resp.Stream != nil {
		if chunked {
			cw := httputil.NewChunkedWriter(hc.bw)
			counter := &countWriter{w: cw}
			err := resp.Stream(&flushWriter{counter, hc.bw})
			written = counter.n
			if err != nil {
				return written, err
			}
			cw.Close()
			hc.bw.WriteString("\r\n")
		} else {
			counter := &countWriter{w: hc.bw}
			err := resp.Stream(&flushWriter{counter, hc.bw})
			written = counter.n
			if err != nil {
				return written, err
			}
		}
		return written, hc.bw.Flush()
	}
	n, err := hc.bw.Write(resp.Body)
	written = int64(n)
	if err != nil {
		return written, err
	}
	return written, hc.bw.Flush()
}

// flushWriter flushes the underlying buffered writer when it gets large, so
// streaming responses are actually streamed.
type flushWriter struct {
	w  io.Writer
	bw *bufio.Writer
}

func (f *flushWriter) Write(p []byte) (int, error) {
	n, err := f.w.Write(p)
	if err != nil {
		return n, err
	}
	if f.bw.Buffered() > 32*1024 {
		if err := f.bw.Flush(); err != nil {
			return n, err
		}
	}
	return n, nil
}
