// buildConfigPre builds the config, leaving Path empty when it was not given.
func buildConfigPre(p *parsedArgs) (*Config, error) {
	hadPath := p.hasPath
	if !hadPath {
		// temporarily pretend the path is "." to let buildConfig succeed
		p.hasPath = true
		p.path = "."
	}
