		if ip.IsUnspecified() {
			hasWildcard = true
			if ip.To4() != nil {
				allV4 = true
			} else {
				allV6 = true
			}
		}
	}
	if hasWildcard {
		ifaces, _ := net.Interfaces()
		for _, iface := range ifaces {
			addrs, err := iface.Addrs()
			if err != nil {
				continue
			}
			for _, a := range addrs {
				var ip net.IP
				switch v := a.(type) {
				case *net.IPNet:
					ip = v.IP
				case *net.IPAddr:
					ip = v.IP
				}
				if ip == nil {
					continue
				}
				if ip.To4() != nil {
					if allV4 {
						ips = append(ips, ip)
					}
				} else if allV6 {
					ips = append(ips, ip)
				}
			}
		}
		sort.Slice(ips, func(i, j int) bool { return ipLess(ips[i], ips[j]) })
	} else {
		ips = cfg.Interfaces
	}
	var out []string
	for _, ip := range ips {
