	}
	return out
}

func ipLess(a, b net.IP) bool {
	a4, b4 := a.To4(), b.To4()
	if a4 != nil && b4 == nil {
		return true
	}
	if a4 == nil && b4 != nil {
		return false
	}
	if a4 != nil {
		return string(a4) < string(b4)
	}
	return string(a.To16()) < string(b.To16())
}

// availableParallelism mimics Rust's std::thread::available_parallelism.
func availableParallelism() int {
	n := runtime.NumCPU()
	// cgroup v2
	if data, err := os.ReadFile("/sys/fs/cgroup/cpu.max"); err == nil {
		f := strings.Fields(string(data))
		if len(f) == 2 && f[0] != "max" {
			q, err1 := strconv.ParseFloat(f[0], 64)
			p, err2 := strconv.ParseFloat(f[1], 64)
			if err1 == nil && err2 == nil && p > 0 {
				c := int(q / p)
				if float64(c) < q/p {
					c++
				}
				if c >= 1 && c < n {
					n = c
				}
			}
		}
	} else if qd, err := os.ReadFile("/sys/fs/cgroup/cpu/cpu.cfs_quota_us"); err == nil {
		pd, err2 := os.ReadFile("/sys/fs/cgroup/cpu/cpu.cfs_period_us")
		if err2 == nil {
			q, _ := strconv.ParseFloat(strings.TrimSpace(string(qd)), 64)
			p, _ := strconv.ParseFloat(strings.TrimSpace(string(pd)), 64)
			if q > 0 && p > 0 {
				c := int(q / p)
				if float64(c) < q/p {
					c++
				}
				if c >= 1 && c < n {
					n = c
				}
			}
		}
	}
	if n < 1 {
		n = 1
	}
	return n
}
