func percentDecode(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '%' && i+2 < len(s)+0 && i+2 <= len(s)-1 {
			h1, ok1 := unhex(s[i+1])
			h2, ok2 := unhex(s[i+2])
			if ok1 && ok2 {
				sb.WriteByte(h1<<4 | h2)
				i += 2
				continue
			}
		}
		sb.WriteByte(s[i])
	}
	return sb.String()
}

func unhex(c byte) (byte, bool) {
	switch {
	case c >= '0' && c <= '9':
		return c - '0', true
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10, true
	case c >= 'A' && c <= 'F':
		return c - 'A' + 10, true
	}
	return 0, false
}

// formQueryDecode decodes application/x-www-form-urlencoded values ('+' is space).
func formQueryDecode(s string) string {
