	case secs <= 90*60:
		s = "an hour"
	case secs <= 22*3600:
		s = fmt.Sprintf("%d hours", maxI64(secs/3600, 2))
	case secs <= 36*3600:
		s = "a day"
	case secs <= 6*86400+12*3600:
		s = fmt.Sprintf("%d days", maxI64(secs/86400, 2))
	case secs <= 10*86400+12*3600:
		s = "a week"
	case secs <= 29*86400:
		s = fmt.Sprintf("%d weeks", maxI64(secs/(7*86400), 2))
	case secs <= 45*86400:
		s = "a month"
	case secs <= 345*86400:
		s = fmt.Sprintf("%d months", maxI64(secs/(30*86400), 2))
	case secs <= 547*86400:
		s = "a year"
	default:
		s = fmt.Sprintf("%d years", maxI64(secs/(365*86400), 2))
	}
	if future {
		return "in " + s
	}
	return s + " ago"
}

func maxI64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

