		cb, sb := utf8.DecodeRuneInString(b[j:])
		if isDigit(ca) && isDigit(cb) {
			// compare numeric runs
			si := i
			for i < len(a) && a[i] >= '0' && a[i] <= '9' {
				i++
			}
			sj := j
			for j < len(b) && b[j] >= '0' && b[j] <= '9' {
				j++
			}
			na := strings.TrimLeft(a[si:i], "0")
			nb := strings.TrimLeft(b[sj:j], "0")
			if len(na) != len(nb) {
				if len(na) < len(nb) {
					return -1
				}
				return 1
			}
			if na != nb {
				if na < nb {
					return -1
				}
				return 1
			}
			// equal numeric value: shorter (fewer leading zeros) first
			la, lb := i-si, j-sj
			if la != lb {
				if la < lb {
					return -1
				}
				return 1
			}
			continue
		}
		if ca != cb {
			if ca < cb {
				return -1
			}
			return 1
		}
		i += sa
		j += sb
	}
	if i < len(a) {
		return 1
	}
	if j < len(b) {
		return -1
	}
	return 0
}

func isDigit(r rune) bool {
	return r >= '0' && r <= '9'
}

func lowerString(s string) string {
	return strings.Map(unicode.ToLower, s)
}
