// pageHead renders the <head> element.
func pageHead(c *Config, title string, withUpload bool) string {
	var sb strings.Builder
	sb.WriteString(`<!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light">`)
	sb.WriteString(`<link rel="icon" type="image/svg+xml" href="` + htmlEscape(c.RoutePrefix) + `/__miniserve_internal/favicon.svg">`)
	sb.WriteString(`<link rel="stylesheet" href="` + htmlEscape(c.RoutePrefix) + `/__miniserve_internal/style.css">`)
	sb.WriteString(`<title>` + htmlEscape(title) + `</title>`)
	sb.WriteString(`<script>` + scriptColor + `</script>`)
	sb.WriteString(`<script>const API_ROUTE = '` + c.RoutePrefix + `/__miniserve_internal/api';` + scriptAPI + `</script>`)
	if withUpload {
		sb.WriteString(fmt.Sprintf(`<script>const CONCURRENCY = %d;`, c.WebUploadConc) + scriptUpload + `</script>`)
	}
	sb.WriteString(`</head>`)
	return sb.String()
}

func versionFooter(c *Config) string {
	if c.HideVersionFoot {
		return ""
	}
	return `<div class="version"><a href="https://github.com/svenstaro/miniserve">miniserve</a>/` + version + `</div>`
}

// renderErrorPage renders the HTML error page.
func renderErrorPage(c *Config, status int, description string, returnAddress string) string {
	statusLine := fmt.Sprintf("%d %s", status, statusText(status))
	var sb strings.Builder
	sb.WriteString(pageHead(c, statusLine, false))
	sb.WriteString(`<body><div class="error"><p>` + htmlEscape(statusLine) + `</p>`)
	if description != "" {
		for _, line := range strings.Split(description, "\n") {
			sb.WriteString(`<p>` + htmlEscape(line) + `</p>`)
		}
	}
	if c.RoutePrefix == "" && !c.DisableIndexing {
		sb.WriteString(`<div class="error-nav"><a class="error-back" href="` + htmlEscape(returnAddress) + `">Go back to file listing</a></div>`)
	}
	sb.WriteString(`<p class="footer">` + versionFooter(c) + `</p></div></body></html>`)
	return sb.String()
}

// Entry describes a directory entry for rendering.
type Entry struct {
	Name          string
	IsDir         bool
	IsSymlink     bool
	SymlinkDest   string // raw link target
	SymlinkIsDir  bool
	Size          uint64
	HasSize       bool
	ModTime       time.Time
	HasModTime    bool
}

// listingParams collects everything needed to render a listing.
type listingParams struct {
	c            *Config
	entries      []Entry
	isRoot       bool
	dirPath      string   // decoded relative dir path from serve root, e.g. "/sub" or "/"
	encodedDir   string   // encoded URL path (without prefix), ends with "/" for non-root? (we keep dir path for links)
	sortMethod   string   // "" if none
	sortOrder    string   // "" if none
	queryString  string   // "?sort=..&order=.." or "?raw=true" or ""
	title        string   // host or custom title
	breadcrumbs  []string // decoded path components
	uploadAllowed bool
	mkdirAllowed bool
	rmAllowed    bool
	readmeName   string
	readmeHTML   string
	qrURL        string
	wgetCmd      string
	now          time.Time
}

func (c *Config) formatSize(n uint64) string {
	if c.SizeExact {
		return fmt.Sprintf("%d B", n)
	}
	return humanSize(n)
}

// buildSortLink renders the sort header/mobile link.
func buildSortLink(name, title, sortMethod, sortOrder string) string {
	link := fmt.Sprintf("?sort=%s&order=asc", name)
	help := fmt.Sprintf("Sort by %s in ascending order", name)
	chevron := "\u25be"
	class := ""
	if sortMethod == name {
		class = "active"
		if sortOrder == "asc" {
			link = fmt.Sprintf("?sort=%s&order=desc", name)
			help = fmt.Sprintf("Sort by %s in descending order", name)
			chevron = "\u25b4"
		}
	}
	return `<span class="` + class + `"><span class="chevron">` + chevron + `</span><a href="` + htmlEscape(link) + `" title="` + htmlEscape(help) + `">` + htmlEscape(title) + `</a></span>`
}

func formatModTime(t time.Time) string {
	// local time with offset like "2020-01-01 00:00:00 +00:00"
	lt := t.Local()
	off := lt.Format("-07:00")
	return lt.Format("2006-01-02 15:04:05") + " " + off
}

func (p *listingParams) entryHref(e Entry) string {
	var base string
	if p.dirPath == "/" {
		base = "/"
	} else {
		base = p.dirPath + "/"
	}
	full := p.c.RoutePrefix + encodeURLPath(base+e.Name)
	if e.IsDir {
		full += "/" + p.queryString
	}
	return full
}

// encodeURLPath percent-encodes each segment of a slash-separated path.
func encodeURLPath(path string) string {
	parts := strings.Split(path, "/")
	for i, part := range parts {
		parts[i] = urlEncodePath(part)
	}
	return strings.Join(parts, "/")
}

func (p *listingParams) renderEntryName(e Entry) string {
	c := p.c
	var sb strings.Builder
	if e.IsDir {
		href := p.entryHref(e)
		if e.IsSymlink && c.ShowSymlinkInfo {
			sb.WriteString(`<a class="symlink" href="` + htmlEscape(href) + `">` + htmlEscape(e.Name) + `/<span class="symlink-symbol"></span><a class="directory">` + htmlEscape(e.SymlinkDest) + `/</a></a>`)
		} else {
			sb.WriteString(`<a class="directory" href="` + htmlEscape(href) + `">` + htmlEscape(e.Name) + `/</a>`)
		}
	} else {
		href := p.entryHref(e)
		if c.FileExternalURL != "" {
			href = c.FileExternalURL + encodeURLPath(strings.TrimSuffix(p.dirPath, "/")+"/"+e.Name)
		}
		if e.IsSymlink && c.ShowSymlinkInfo {
			sb.WriteString(`<a class="symlink" href="` + htmlEscape(href) + `">` + htmlEscape(e.Name) + `<span class="symlink-symbol"></span><a class="file">` + htmlEscape(e.SymlinkDest) + `</a></a>`)
		} else {
			sb.WriteString(`<a class="file" href="` + htmlEscape(href) + `">` + htmlEscape(e.Name) + `</a>`)
		}
	}
	return sb.String()
}

func (p *listingParams) renderEntryRow(e Entry, raw bool) string {
	c := p.c
	var sb strings.Builder
	cls := "entry-type-file"
	if e.IsDir {
		cls = "entry-type-directory"
	}
	sb.WriteString(`<tr class="` + cls + `"><td><p>`)
	sb.WriteString(p.renderEntryName(e))
	if !e.IsDir && !raw {
		sizeText := ""
		if e.HasSize {
			sizeText = c.formatSize(e.Size)
		}
		sb.WriteString(`<span class="mobile-info size">` + buildSortLink("size", sizeText, p.sortMethod, p.sortOrder) + `</span>`)
		if e.HasModTime {
			sb.WriteString(`<span class="mobile-info history">` + buildSortLink("date", humanTime(e.ModTime, p.now), p.sortMethod, p.sortOrder) + `</span>`)
		}
	}
	sb.WriteString(`</p></td>`)
	sb.WriteString(`<td class="size-cell">`)
	if !e.IsDir && e.HasSize {
		sb.WriteString(htmlEscape(c.formatSize(e.Size)))
	}
	sb.WriteString(`</td>`)
	sb.WriteString(`<td class="date-cell">`)
	if e.HasModTime {
		sb.WriteString(`<span>` + formatModTime(e.ModTime) + ` </span>`)
		sb.WriteString(`<span class="history">` + humanTime(e.ModTime, p.now) + `</span>`)
	}
	sb.WriteString(`</td>`)
	if !raw && c.RmEnabled {
		sb.WriteString(`<td class="actions-cell">`)
		if p.rmAllowed {
			rmPath := strings.TrimSuffix(p.dirPath, "/") + "/" + e.Name
			sb.WriteString(`<form class="rm_form" action="` + htmlEscape(c.RoutePrefix+"/rm?path="+encodeURLPath(rmPath)) + `" method="POST"><button type="submit" title="Delete">` + "\u2717" + `</button></form>`)
		}
		sb.WriteString(`</td>`)
	}
	sb.WriteString(`</tr>`)
	return sb.String()
}

// renderRawListing renders the minimal listing used with ?raw=true.
func renderRawListing(p *listingParams) string {
	var sb strings.Builder
	sb.WriteString(`<!DOCTYPE html><html><body><table><thead><th class="name">Name</th><th class="size">Size</th><th class="date">Last modification</th></thead><tbody>`)
	if !p.isRoot {
		sb.WriteString(`<tr><td colspan="3"><p><a class="root" href="` + htmlEscape("../"+p.queryString) + `">..</a></p></td></tr>`)
	}
	for _, e := range p.entries {
		sb.WriteString(p.renderEntryRow(e, true))
	}
	sb.WriteString(`</tbody></table></body></html>`)
	return sb.String()
}

// renderListing renders the full directory listing page.
func renderListing(p *listingParams) string {
	c := p.c
	var sb strings.Builder
	title := p.title
	if len(p.breadcrumbs) > 0 {
		title = title + "/" + strings.Join(p.breadcrumbs, "/")
	}
	sb.WriteString(pageHead(c, title, c.UploadEnabled))
	sb.WriteString(`<body id="drop-container">`)
	sb.WriteString(`<div class="toolbar_box_group">`)
	if c.UploadEnabled {
		sb.WriteString(`<div class="drag-form"><div class="form_title"><h1>Drop your file here to upload it</h1></div></div>`)
	}
	if c.MkdirEnabled {
		sb.WriteString(`<div class="form"><div class="form_title"><h1>Create a new directory</h1></div></div>`)
	}
	sb.WriteString(`</div>`)
	sb.WriteString(`<nav>`)
	if c.QRCode {
		sb.WriteString(`<div><p>QR code</p><div class="qrcode" id="qrcode" title="` + htmlEscape(p.qrURL) + `">` + qrSVG(p.qrURL) + `</div></div>`)
	}
	if !c.HideThemeSel {
		sb.WriteString(`<div><p>Change theme...</p><ul class="theme">`)
		for _, t := range themes {
			sb.WriteString(`<li data-theme="` + t.id + `"><a href="javascript:updateColorScheme(&quot;` + t.id + `&quot;)" title="Switch to ` + t.name + ` theme">` + t.name + `</a></li>`)
		}
		sb.WriteString(`</ul></div>`)
	}
	sb.WriteString(`</nav>`)
	sb.WriteString(`<div class="container"><span id="top"></span>`)
	// title / breadcrumbs
	sb.WriteString(`<h1 class="title" dir="ltr">`)
	if len(p.breadcrumbs) == 0 {
		sb.WriteString(`<span><bdi>` + htmlEscape(p.title) + `</bdi></span>/`)
	} else {
		rootHref := c.RoutePrefix + "/" + p.queryString
		sb.WriteString(`<a href="` + htmlEscape(rootHref) + `"><bdi>` + htmlEscape(p.title) + `</bdi></a>/`)
		acc := ""
		for i, comp := range p.breadcrumbs {
			acc += "/" + comp
			if i == len(p.breadcrumbs)-1 {
				sb.WriteString(`<span><bdi>` + htmlEscape(comp) + `</bdi></span>/`)
			} else {
				href := c.RoutePrefix + encodeURLPath(acc) + "/" + p.queryString
				sb.WriteString(`<a href="` + htmlEscape(href) + `"><bdi>` + htmlEscape(comp) + `</bdi></a>/`)
			}
		}
	}
	sb.WriteString(`</h1>`)
	// toolbar
	sb.WriteString(`<div class="toolbar">`)
	if c.archivesEnabled() {
		sb.WriteString(`<div class="download">`)
		sep := "?"
		if p.queryString != "" {
			sep = p.queryString + "&"
		}
		if c.EnableTarGz {
			sb.WriteString(`<a href="` + htmlEscape(sep+"download=tar_gz") + `">Download .tar.gz</a>`)
		}
		if c.EnableTar {
			sb.WriteString(`<a href="` + htmlEscape(sep+"download=tar") + `">Download .tar</a>`)
		}
		if c.EnableZip {
			sb.WriteString(`<a href="` + htmlEscape(sep+"download=zip") + `">Download .zip</a>`)
		}
		sb.WriteString(`</div>`)
	}
	sb.WriteString(`<div class="toolbar_box_group">`)
	uploadPath := encodeURLPath(strings.TrimSuffix(p.dirPath, "/"))
	if uploadPath == "" {
		uploadPath = "/"
	}
	if p.uploadAllowed {
		action := c.RoutePrefix + "/upload?path=" + uploadPath
		if p.queryString != "" {
			action += "&" + strings.TrimPrefix(p.queryString, "?")
		}
		accept := ""
		if len(c.MediaTypes) > 0 {
			accept = ` accept="` + htmlEscape(strings.Join(c.MediaTypes, ",")) + `"`
		}
		sb.WriteString(`<div class="toolbar_box"><form id="file_submit" action="` + htmlEscape(action) + `" method="POST" enctype="multipart/form-data"><p>Select a file to upload or drag it anywhere into the window</p><div><input id="file-input"` + accept + ` type="file" name="file_to_upload" required="" multiple></input><button type="submit">Upload file</button></div></form></div>`)
	}
	if p.mkdirAllowed {
		action := c.RoutePrefix + "/upload?path=" + uploadPath
		sb.WriteString(`<div class="toolbar_box"><form id="mkdir" action="` + htmlEscape(action) + `" method="POST" enctype="multipart/form-data"><p>Specify a directory name to create</p><div class="toolbar_box"><input type="text" name="mkdir" required="" placeholder="Directory name"></input><button type="submit">Create directory</button></div></form></div>`)
	}
	sb.WriteString(`</div></div>`)
	// table
	sb.WriteString(`<table><thead>`)
	sb.WriteString(`<th class="name">` + buildSortLink("name", "Name", p.sortMethod, p.sortOrder) + `</th>`)
	sb.WriteString(`<th class="size">` + buildSortLink("size", "Size", p.sortMethod, p.sortOrder) + `</th>`)
	sb.WriteString(`<th class="date">` + buildSortLink("date", "Last modification", p.sortMethod, p.sortOrder) + `</th>`)
	if c.RmEnabled {
		sb.WriteString(`<th class="actions"><span>Actions</span></th>`)
	}
	sb.WriteString(`</thead><tbody>`)
	if !p.isRoot {
		colspan := 3
		if c.RmEnabled {
			colspan = 4
		}
		sb.WriteString(fmt.Sprintf(`<tr><td colspan="%d"><p><span class="root-chevron">`+"\u25c2"+`</span><a class="root" href="%s">Parent directory</a></p></td></tr>`, colspan, htmlEscape("../"+p.queryString)))
	}
	for _, e := range p.entries {
		sb.WriteString(p.renderEntryRow(e, false))
	}
	sb.WriteString(`</tbody></table>`)
	if p.readmeName != "" {
		sb.WriteString(`<div id="readme"><h3 id="readme-filename">` + htmlEscape(p.readmeName) + `</h3><div id="readme-contents">` + p.readmeHTML + `</div></div>`)
	}
	sb.WriteString(`<a class="back" href="#top">` + "\u21ea" + `</a>`)
	sb.WriteString(`<div class="footer">`)
	if c.ShowWgetFooter {
		sb.WriteString(`<div class="downloadDirectory"><p>Download folder:</p><a class="cmd" title="Click to copy!" style="cursor: pointer;" onclick="navigator.clipboard.writeText(&quot;` + htmlEscape(p.wgetCmd) + `&quot;)">` + htmlEscape(p.wgetCmd) + `</a></div>`)
	}
	sb.WriteString(versionFooter(c))
	sb.WriteString(`</div></div>`)
	sb.WriteString(uploadAreaHTML)
	sb.WriteString(`</body></html>`)
	return sb.String()
}

const uploadAreaHTML = `<div class="upload_area" id="upload_area"><template id="upload_file_item"><li class="upload_file_item"><div class="upload_file_container"><div class="upload_file_text"><span class="file_upload_percent"></span> - <span class="file_size"></span> - <span class="file_name"></span></div><button class="file_cancel_upload">` + "\u2716" + `</button></div><div class="file_progress_bar"></div></li></template><div class="upload_container"><div class="upload_header"><h4 style="margin:0px" id="upload_title"></h4><svg id="upload-toggle" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="size-6"><path stroke-linecap="round" stroke-linejoin="round" d="m4.5 15.75 7.5-7.5 7.5 7.5"></path></svg></div><div class="upload_action"><p id="upload_action_text">Starting upload...</p><button class="upload_cancel" id="upload_cancel">CANCEL</button></div><div class="upload_files"><ul class="upload_file_list" id="upload_file_list"></ul></div></div></div>`
EOF
echo ok"}

