func parseHTTPDate(s string) (time.Time, bool) {
	s = strings.TrimSpace(s)
	layouts := []string{time.RFC1123, time.RFC850, time.ANSIC}
	for _, l := range layouts {
		t, err := time.Parse(l, s)
		if err == nil {
			// validate weekday
			wd := t.Weekday().String()
			short := wd[:3]
			if strings.HasPrefix(s, wd+",") || strings.HasPrefix(s, short+",") || strings.HasPrefix(s, short+" ") {
				return t, true
			}
			return time.Time{}, false
		}
	}
	return time.Time{}, false
}

// etagMatches checks an If-Match / If-None-Match header list against the etag.
func etagMatches(header, etag string, weak bool) bool {
	header = strings.TrimSpace(header)
	if header == "*" {
		return true
	}
	for _, part := range strings.Split(header, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if weak {
			part = strings.TrimPrefix(part, "W/")
		} else if strings.HasPrefix(part, "W/") {
			continue
		}
		if part == etag {
			return true
		}
	}
	return false
}

type byteRange struct {
	start, length int64
}

// parseRange parses a Range header (first satisfiable range only, like actix-files).
func parseRange(header string, size int64) ([]byteRange, bool) {
	if !strings.HasPrefix(header, "bytes=") {
		return nil, false
	}
	var ranges []byteRange
	for _, part := range strings.Split(header[6:], ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		i := strings.IndexByte(part, '-')
		if i < 0 {
			return nil, false
		}
		startS := strings.TrimSpace(part[:i])
		endS := strings.TrimSpace(part[i+1:])
		var start, end int64
		if startS == "" {
			// suffix range
			if endS == "" {
				return nil, false
			}
			n, err := strconv.ParseInt(endS, 10, 64)
			if err != nil || n < 0 {
				return nil, false
			}
			if n > size {
				n = size
			}
			start = size - n
			end = size - 1
			if n == 0 {
				continue
			}
		} else {
			var err error
			start, err = strconv.ParseInt(startS, 10, 64)
			if err != nil || start < 0 {
				return nil, false
			}
			if endS == "" {
				end = size - 1
			} else {
				end, err = strconv.ParseInt(endS, 10, 64)
				if err != nil {
					return nil, false
				}
				if end >= size {
					end = size - 1
				}
			}
			if start > end || start >= size {
				continue
			}
		}
		ranges = append(ranges, byteRange{start, end - start + 1})
	}
	return ranges, true
}

// serveFile builds a response for a regular file following actix-files semantics.
func (s *Server) serveFile(req *Request, path string, displayName string) *Response {
	m, st, err := statMeta(path)
	if err != nil {
		return nil
	}
	if st.IsDir() {
		return nil
	}
	f, err := os.Open(path)
	if err != nil {
		return nil
	}
	ct := equivUTF8Text(guessMime(displayName))
	disp := contentDisposition(displayName, guessMime(displayName))
	lastMod := httpDate(m.modTime)

	resp := newResponse(200)
	resp.SetHeader("content-type", ct)
	resp.SetHeader("content-disposition", disp)
	resp.SetHeader("last-modified", lastMod)
	resp.SetHeader("etag", m.etag)
	resp.SetHeader("accept-ranges", "bytes")

	// preconditions
	preconditionFailed := false
	if im := req.Header.Get("If-Match"); im != "" {
		if !etagMatches(im, m.etag, false) {
			preconditionFailed = true
		}
	} else if ius := req.Header.Get("If-Unmodified-Since"); ius != "" {
		if t, ok := parseHTTPDate(ius); ok {
			if m.modTime.Unix() > t.Unix() {
				preconditionFailed = true
			}
		}
	}
	notModified := false
	if inm := req.Header.Get("If-None-Match"); inm != "" {
		notModified = etagMatches(inm, m.etag, true)
	} else if ims := req.Header.Get("If-Modified-Since"); ims != "" {
		if t, ok := parseHTTPDate(ims); ok {
			if m.modTime.Unix() <= t.Unix() {
				notModified = true
			}
		}
	}
	if preconditionFailed {
		f.Close()
		resp.Status = 412
		resp.Body = []byte(renderErrorPage(s.cfg, 412, "", returnAddress(req)))
		resp.SetHeader("content-type", "text/html")
		return resp
	}
	if notModified {
		f.Close()
		resp.Status = 304
		resp.NoContentLength = true
		return resp
	}

	length := m.size
	offset := int64(0)
	if rng := req.Header.Get("Range"); rng != "" {
		ranges, ok := parseRange(rng, m.size)
		if ok && len(ranges) > 0 {
			offset = ranges[0].start
			length = ranges[0].length
			resp.SetHeader("content-range", fmt.Sprintf("bytes %d-%d/%d", offset, offset+length-1, m.size))
			resp.Status = 206
		} else {
			f.Close()
			resp.Status = 416
			resp.SetHeader("content-range", fmt.Sprintf("bytes */%d", m.size))
			resp.Body = []byte(renderErrorPage(s.cfg, 416, "", returnAddress(req)))
			resp.SetHeader("content-type", "text/html")
			return resp
		}
	}
	if req.Method == "HEAD" {
		f.Close()
		resp.Body = make([]byte, 0)
		resp.fixedLength = length
		return resp
	}
	resp.fixedLength = length
	resp.BodyReader = &sectionReader{f: f, off: offset, remaining: length}
	return resp
}

type sectionReader struct {
	f         *os.File
	off       int64
	remaining int64
}

func (r *sectionReader) Read(p []byte) (int, error) {
	if r.remaining <= 0 {
		return 0, io.EOF
	}
	if int64(len(p)) > r.remaining {
		p = p[:r.remaining]
	}
	n, err := r.f.ReadAt(p, r.off)
	r.off += int64(n)
	r.remaining -= int64(n)
	if err == io.EOF && r.remaining > 0 && n > 0 {
		err = nil
	}
	return n, err
}

func (r *sectionReader) Close() error { return r.f.Close() }

func returnAddress(req *Request) string {
	if ref := req.Header.Get("Referer"); ref != "" {
		return ref
	}
	return "/"
}
EOF
