		if !resp.HasHeader(h.name) {
			resp.AddHeader(h.name, h.value)
		}
	}
	if s.cfg.Compress {
		resp = compressResponse(req, resp)
	}
	return resp
}

func (s *Server) route(req *Request) *Response {
	c := s.cfg
	path := req.RawPath
	if path == "" {
		path = "/"
	}
	// route prefix
	rel := path
	if c.RoutePrefix != "" {
		if path == c.RoutePrefix {
			if c.PathIsFile {
				rel = "/"
			} else {
				return s.redirect(307, c.RoutePrefix+"/")
			}
		} else if strings.HasPrefix(path, c.RoutePrefix+"/") {
			rel = path[len(c.RoutePrefix):]
		} else {
			return s.routeNotFound(req)
		}
	}

	// internal assets (not authenticated)
	if rel == "/__miniserve_internal/style.css" && (req.Method == "GET") {
		r := newResponse(200)
		r.SetHeader("content-type", "text/css")
		r.Body = []byte(fullCSS(c))
		return r
	}
	if rel == "/__miniserve_internal/favicon.svg" && (req.Method == "GET") {
		r := newResponse(200)
		r.SetHeader("content-type", "image/svg+xml")
		r.Body = faviconSVG
		return r
	}
	if rel == "/__miniserve_internal/api" && req.Method == "POST" {
		return s.handleAPI(req)
	}

	// authentication
	if len(c.Auth) > 0 {
		if r := s.checkAuth(req); r != nil {
			return r
		}
	}

	if c.UploadEnabled && rel == "/upload" {
		if req.Method != "POST" {
			r := newResponse(405)
			r.SetHeader("allow", "POST")
			return r
		}
		return s.handleUpload(req, rel)
	}
	if c.RmEnabled && rel == "/rm" {
		if req.Method != "POST" {
			r := newResponse(405)
			r.SetHeader("allow", "POST")
			return r
		}
		return s.handleRm(req)
	}
	if c.EnableWebdav && (req.Method == "PROPFIND" || req.Method == "OPTIONS") {
		return s.handleWebdav(req, rel)
	}

	if c.PathIsFile {
		if rel == "/" {
			if req.Method != "GET" && req.Method != "HEAD" {
				return s.routeNotFound(req)
			}
			if r := s.serveFile(req, c.Path, filepath.Base(c.Path)); r != nil {
				return r
			}
			return plainError(404, "No such file or directory (os error 2)")
		}
		return s.routeNotFound(req)
	}

	if req.Method != "GET" && req.Method != "HEAD" {
		return s.routeNotFound(req)
	}
	return s.serveFiles(req, rel)
}

func (s *Server) redirect(status int, location string) *Response {
	r := newResponse(status)
	r.SetHeader("location", location)
	return r
}

// checkAuth validates HTTP basic authentication.
func (s *Server) checkAuth(req *Request) *Response {
	authHdr := req.Header.Get("Authorization")
	unauthorized := func() *Response {
		r := newResponse(401)
		r.SetHeader("www-authenticate", "Basic")
		return r
	}
	if authHdr == "" {
		return unauthorized()
	}
	if !strings.HasPrefix(authHdr, "Basic ") {
		return unauthorized()
	}
	encoded := authHdr[6:]
	if strings.HasPrefix(encoded, " ") {
		return unauthorized()
	}
	decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(encoded))
	if err != nil {
		return unauthorized()
	}
	i := strings.IndexByte(string(decoded), ':')
	if i < 0 {
		return unauthorized()
	}
	user := string(decoded[:i])
	pass := string(decoded[i+1:])
	for _, a := range s.cfg.Auth {
		if a.matches(user, pass) {
			return nil
		}
	}
	desc := "Invalid credentials for HTTP authentication"
	logErrorChain(desc)
	r := s.htmlError(req, 401, desc)
	r.SetHeader("www-authenticate", "Basic realm=\"miniserve\"")
	return r
}

// pathParseError mirrors actix-files UriSegmentError.
type pathParseError struct {
	msg string
}

// parseURLPath validates and decodes a URL path into relative components.
func (s *Server) parseURLPath(raw string) ([]string, *pathParseError) {
	segmentCount := strings.Count(raw, "/") + 1
	decoded := percentDecode(raw)
	if strings.Count(decoded, "/")+1 != segmentCount {
		return nil, &pathParseError{"segment contained invalid character ('/')"}
	}
	var buf []string
	for _, segment := range strings.Split(decoded, "/") {
		switch {
		case segment == "..":
			if len(buf) > 0 {
				buf = buf[:len(buf)-1]
			}
		case !s.cfg.ShowHidden && strings.HasPrefix(segment, "."):
			return nil, &pathParseError{"segment started with invalid character: ('.')"}
		case strings.HasPrefix(segment, "*"):
			return nil, &pathParseError{"segment started with invalid character: ('*')"}
		case strings.HasSuffix(segment, ":"):
			return nil, &pathParseError{"segment ended with invalid character: (':')"}
		case strings.HasSuffix(segment, ">"):
			return nil, &pathParseError{"segment ended with invalid character: ('>')"}
		case strings.HasSuffix(segment, "<"):
			return nil, &pathParseError{"segment ended with invalid character: ('<')"}
		case segment == "":
			continue
		default:
			buf = append(buf, segment)
		}
	}
	return buf, nil
}

// containsSymlink reports whether any component of the relative path is a symlink.
func containsSymlink(base string, comps []string) bool {
	p := base
	for _, c := range comps {
		p = filepath.Join(p, c)
		st, err := os.Lstat(p)
		if err != nil {
			return false
		}
		if st.Mode()&os.ModeSymlink != 0 {
			return true
		}
	}
	return false
}

// serveFiles implements the Files service: directories, listings and files.
func (s *Server) serveFiles(req *Request, rel string) *Response {
	c := s.cfg
	comps, perr := s.parseURLPath(rel)
	if perr != nil {
		return s.htmlError(req, 400, perr.msg)
	}
	if c.NoSymlinks && containsSymlink(c.Path, comps) {
		return s.notFoundFallback(req, rel, comps)
	}
	diskPath := filepath.Join(append([]string{c.Path}, comps...)...)
	st, err := os.Stat(diskPath)
	if err != nil {
		return s.notFoundFallback(req, rel, comps)
	}
	if st.IsDir() {
		if !strings.HasSuffix(rel, "/") {
			return s.redirect(307, req.RawPath+"/")
		}
		if c.Index != "" {
			idx := filepath.Join(diskPath, c.Index)
			if ist, err := os.Stat(idx); err == nil && !ist.IsDir() {
				if r := s.serveFile(req, idx, c.Index); r != nil {
					return r
				}
			}
		}
		return s.directoryListing(req, rel, comps, diskPath)
	}
	if r := s.serveFile(req, diskPath, filepath.Base(diskPath)); r != nil {
		return r
	}
	return s.notFoundFallback(req, rel, comps)
}

// notFoundFallback handles missing paths: pretty urls, SPA or 404.
func (s *Server) notFoundFallback(req *Request, rel string, comps []string) *Response {
	c := s.cfg
	if c.PrettyURLs {
		diskPath := filepath.Join(append([]string{c.Path}, comps...)...) + ".html"
		if strings.HasSuffix(rel, "/") || len(comps) == 0 {
			diskPath = filepath.Join(append([]string{c.Path}, comps...)...) + "/.html"
		}
		if r := s.serveFile(req, diskPath, filepath.Base(diskPath)); r != nil {
			return r
		}
		_, err := os.Stat(diskPath)
		if err != nil {
			return plainError(ioErrStatus(err), osErr(err))
		}
		return plainError(404, "No such file or directory (os error 2)")
	}
	if c.SPA && c.Index != "" {
		idx := filepath.Join(c.Path, c.Index)
		if r := s.serveFile(req, idx, c.Index); r != nil {
			return r
		}
		_, err := os.Stat(idx)
		if err != nil {
			return plainError(ioErrStatus(err), osErr(err))
		}
		return plainError(404, "No such file or directory (os error 2)")
	}
	return s.routeNotFound(req)
}

func ioErrStatus(err error) int {
	if os.IsNotExist(err) {
		return 404
	}
	if os.IsPermission(err) {
		return 403
	}
	return 500
}
EOF
echo ok

