				return queryParams{}
			}
			qp.sort = v
		case "order":
			if v != "asc" && v != "desc" {
				return queryParams{}
			}
			qp.order = v
		case "raw":
			if v == "true" {
				qp.raw = true
			} else if v != "false" {
				return queryParams{}
			}
		case "download":
			if v != "tar" && v != "tar_gz" && v != "zip" {
				return queryParams{}
			}
			qp.download = v
		case "path":
			qp.path = v
			qp.hasPath = true
		case "mkdir":
			qp.mkdir = v
			qp.hasMkdir = true
		}
	}
	return qp
}

// linkQuery returns the query string appended to directory links.
func (qp queryParams) linkQuery() string {
	if qp.raw {
		return "?raw=true"
	}
	if qp.sort != "" && qp.order != "" {
		return fmt.Sprintf("?sort=%s&order=%s", qp.sort, qp.order)
	}
	return ""
}

// readEntries reads a directory into Entry values following miniserve's rules.
func (s *Server) readEntries(diskPath string) ([]Entry, error) {
	c := s.cfg
	f, err := os.Open(diskPath)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	names, err := f.Readdirnames(-1)
	if err != nil {
		return nil, err
	}
	var entries []Entry
	for _, name := range names {
		if !c.ShowHidden && strings.HasPrefix(name, ".") {
			continue
		}
		full := filepath.Join(diskPath, name)
		lst, err := os.Lstat(full)
		if err != nil {
			continue
		}
		isSymlink := lst.Mode()&os.ModeSymlink != 0
		st := lst
		if isSymlink {
			st, err = os.Stat(full)
			if err != nil {
				continue
			}
		}
		if c.NoSymlinks && isSymlink {
			continue
		}
		e := Entry{Name: name, IsSymlink: isSymlink}
		if isSymlink && c.ShowSymlinkInfo {
			if dest, err := os.Readlink(full); err == nil {
				e.SymlinkDest = dest
			}
		}
		e.ModTime = st.ModTime()
		e.HasModTime = true
		if st.IsDir() {
			e.IsDir = true
		} else if st.Mode().IsRegular() {
			e.Size = uint64(st.Size())
			e.HasSize = true
		} else {
			continue
		}
		entries = append(entries, e)
	}
	return entries, nil
}

// sortEntries sorts entries according to method/order and dirs-first.
func sortEntries(entries []Entry, method, order string, dirsFirst bool) {
	switch method {
	case "size":
		sort.SliceStable(entries, func(i, j int) bool {
			return entries[j].Size < entries[i].Size
		})
	case "date":
		sort.SliceStable(entries, func(i, j int) bool {
			return entries[j].ModTime.Before(entries[i].ModTime)
		})
	default:
		sort.SliceStable(entries, func(i, j int) bool {
			return naturalCompare(lowerString(entries[i].Name), lowerString(entries[j].Name)) < 0
		})
	}
	if order == "asc" {
		for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
			entries[i], entries[j] = entries[j], entries[i]
		}
	}
	if dirsFirst {
		sort.SliceStable(entries, func(i, j int) bool {
			return entries[i].IsDir && !entries[j].IsDir
		})
	}
}

// requestHost returns the host used for titles and URLs (honours X-Forwarded-Host).
func requestHost(req *Request) string {
	if h := req.Header.Get("X-Forwarded-Host"); h != "" {
		if i := strings.IndexByte(h, ','); i >= 0 {
			h = h[:i]
		}
		return strings.TrimSpace(h)
	}
	if fwd := req.Header.Get("Forwarded"); fwd != "" {
		for _, part := range strings.Split(fwd, ";") {
			part = strings.TrimSpace(part)
			if strings.HasPrefix(strings.ToLower(part), "host=") {
				return strings.Trim(part[5:], "\"")
			}
		}
	}
	if h := req.Header.Get("Host"); h != "" {
		return h
	}
	return ""
}

func requestScheme(req *Request, c *Config) string {
	if p := req.Header.Get("X-Forwarded-Proto"); p != "" {
		if i := strings.IndexByte(p, ','); i >= 0 {
			p = p[:i]
		}
		return strings.TrimSpace(p)
	}
	if fwd := req.Header.Get("Forwarded"); fwd != "" {
		for _, part := range strings.Split(fwd, ";") {
			part = strings.TrimSpace(part)
			if strings.HasPrefix(strings.ToLower(part), "proto=") {
				return strings.Trim(part[6:], "\"")
			}
		}
	}
	if req.TLS {
		return "https"
	}
	return "http"
}

// isPathAllowed checks whether rel (components) lies within one of the allowed dirs.
func isPathAllowed(allowed []string, comps []string) bool {
	if len(allowed) == 0 {
		return true
	}
	rel := strings.Join(comps, "/")
	for _, a := range allowed {
		if a == "" || rel == a || strings.HasPrefix(rel, a+"/") {
			return true
		}
	}
	return false
}

var readmeNames = map[string]bool{"readme": true, "readme.md": true, "readme.txt": true}

// directoryListing renders a directory (or an archive of it).
func (s *Server) directoryListing(req *Request, rel string, comps []string, diskPath string) *Response {
	c := s.cfg
	qp := parseQueryParams(req.RawQuery)

	if c.DisableIndexing {
		r := newResponse(404)
		r.SetHeader("content-type", "text/html")
		r.Body = []byte(renderErrorPage(c, 404, "File not found.", returnAddress(req)))
		return r
	}

	if qp.download != "" {
		return s.serveArchive(req, qp.download, diskPath, comps)
	}

	entries, err := s.readEntries(diskPath)
	if err != nil {
		return s.htmlError(req, 500, osErr(err))
	}
	method := c.DefaultSortMeth
	if qp.sort != "" {
		method = qp.sort
	}
	order := c.DefaultSortOrder
	if qp.order != "" {
		order = qp.order
	}

	// readme detection happens in directory order
	var readmeName, readmeHTML string
	if c.Readme {
		for _, e := range entries {
			if !e.IsDir && readmeNames[strings.ToLower(e.Name)] {
				data, err := os.ReadFile(filepath.Join(diskPath, e.Name))
				if err != nil {
					continue
				}
				readmeName = e.Name
				if strings.HasSuffix(strings.ToLower(e.Name), ".md") {
					readmeHTML = renderMarkdown(string(data))
				} else {
					readmeHTML = "<pre>" + string(data) + "</pre>"
				}
			}
		}
	}

	sortEntries(entries, method, order, c.DirsFirst)

	dirPath := "/" + strings.Join(comps, "/")
	host := requestHost(req)
	title := c.Title
	if title == "" {
		title = host
	}
	scheme := requestScheme(req, c)
	fullURL := scheme + "://" + host + req.RawPath

	p := &listingParams{
		c:           c,
		entries:     entries,
		isRoot:      len(comps) == 0,
		dirPath:     dirPath,
		sortMethod:  qp.sort,
		sortOrder:   qp.order,
		queryString: qp.linkQuery(),
		title:       title,
		breadcrumbs: comps,
		uploadAllowed: c.UploadEnabled && isPathAllowed(c.AllowedUploadDir, comps),
		mkdirAllowed:  c.UploadEnabled && c.MkdirEnabled && isPathAllowed(c.AllowedUploadDir, comps),
		rmAllowed:     c.RmEnabled && isPathAllowed(c.AllowedRmDir, comps),
		readmeName:  readmeName,
		readmeHTML:  readmeHTML,
		qrURL:       fullURL,
		now:         time.Now(),
	}
	if c.ShowWgetFooter {
		depth := len(strings.Split(strings.Trim(req.RawPath, "/"), "/"))
		if strings.Trim(req.RawPath, "/") == "" {
			depth = 0
		}
		var opt string
		switch {
		case depth == 0:
			opt = fmt.Sprintf(" -P '%s'", host)
		case depth == 1:
			opt = ""
		default:
			opt = fmt.Sprintf(" --cut-dirs=%d", depth-1)
		}
		p.wgetCmd = fmt.Sprintf("wget -rcnp -R 'index.html*' -nH%s '%s?raw=true'", opt, fullURL)
	}

	var body string
	if qp.raw {
		body = renderRawListing(p)
	} else {
		body = renderListing(p)
	}
	r := newResponse(200)
	r.SetHeader("content-type", "text/html; charset=utf-8")
	r.Body = []byte(body)
	return r
}

// dirSize computes the total size of all files below a directory.
func dirSize(path string) (uint64, error) {
	var total uint64
	err := walkDirSize(path, &total)
	return total, err
}

func walkDirSize(path string, total *uint64) error {
	entries, err := os.ReadDir(path)
	if err != nil {
		return err
	}
	for _, e := range entries {
		full := filepath.Join(path, e.Name())
		st, err := os.Stat(full)
		if err != nil {
			continue
		}
		if st.IsDir() {
			if e.Type()&os.ModeSymlink != 0 {
				continue
			}
			walkDirSize(full, total)
		} else {
			*total += uint64(st.Size())
		}
	}
	return nil
}
