func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	out, err := os.OpenFile(dst, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600)
	if err != nil {
		return err
	}
	if _, err := io.Copy(out, in); err != nil {
		out.Close()
		return err
	}
	return out.Close()
}

// parseQueryParamsStrict parses the query and returns nil on any error.
func parseQueryParamsStrict(q string) *queryParams {
	var qp queryParams
	seen := map[string]bool{}
	for _, kv := range parseQuery(q) {
		k, v := kv[0], kv[1]
		switch k {
		case "sort", "order", "raw", "download", "path", "mkdir":
			if seen[k] {
				return nil
			}
			seen[k] = true
		}
		switch k {
		case "sort":
			if v != "name" && v != "size" && v != "date" {
				return nil
			}
			qp.sort = v
		case "order":
			if v != "asc" && v != "desc" {
				return nil
			}
			qp.order = v
		case "raw":
			if v == "true" {
				qp.raw = true
			} else if v != "false" {
				return nil
			}
		case "download":
			if v != "tar" && v != "tar_gz" && v != "zip" {
				return nil
			}
			qp.download = v
		case "path":
			qp.path = v
			qp.hasPath = true
		case "mkdir":
			qp.mkdir = v
			qp.hasMkdir = true
		}
	}
	return &qp
}

