func (s *Server) handleRm(req *Request) *Response {
	c := s.cfg
	qp := parseQueryParamsStrict(req.RawQuery)
	if qp == nil || !qp.hasPath {
		return s.htmlError(req, 400, "Query deserialize error: missing field `path`")
	}
	comps := sanitizeComponents(qp.path)
	if !c.ShowHidden && hasHiddenComponent(comps) {
		desc := "Invalid path\ncaused by: Invalid value for 'path' parameter"
		logErrorChain(desc)
		return s.htmlError(req, 400, desc)
	}
	target := filepath.Join(append([]string{c.Path}, comps...)...)
	if _, err := os.Lstat(target); err != nil {
		desc := "Invalid HTTP request\ncaused by: Invalid value for 'path' parameter"
		logErrorChain(desc)
		return s.htmlError(req, 400, desc)
	}
	if !isPathAllowed(c.AllowedRmDir, comps) || len(comps) == 0 && len(c.AllowedRmDir) > 0 {
		desc := "Remove not allowed to this directory"
		logErrorChain(desc)
		return s.htmlError(req, 403, desc)
	}
	st, err := os.Lstat(target)
	if err == nil {
		if st.IsDir() {
			err = os.RemoveAll(target)
		} else {
			err = os.Remove(target)
		}
	}
	if err != nil {
		desc := fmt.Sprintf("Failed to remove %s\ncaused by: %s", target, osErr(err))
		logErrorChain(desc)
		return s.htmlError(req, 500, desc)
	}
	return s.redirect(303, returnAddress(req))
}

// handleAPI implements the directory size API.
func (s *Server) handleAPI(req *Request) *Response {
	c := s.cfg
	ct := req.Header.Get("Content-Type")
	mediatype, _, err := mime.ParseMediaType(ct)
	if err != nil || (mediatype != "application/json" && !strings.HasSuffix(mediatype, "+json")) {
		return s.htmlError(req, 400, "Content type error")
	}
	data, _ := io.ReadAll(io.LimitReader(req.Body, 2*1024*1024))
	cmd, arg, jerr := parseAPICommand(data)
	if jerr != "" {
		return s.htmlError(req, 400, "Json deserialize error: "+jerr)
	}
	if cmd != "DirSize" {
		return s.htmlError(req, 400, "Json deserialize error: unknown variant `"+cmd+"`, expected `DirSize`")
	}
	if !c.DirectorySize {
		r := newResponse(200)
		r.SetHeader("content-type", "text/plain; charset=utf-8")
		r.Body = []byte("-")
		return r
	}
	comps := sanitizeComponents(arg)
	target := filepath.Join(append([]string{c.Path}, comps...)...)
	size, err := dirSize(target)
	if err != nil {
		desc := "Invalid path\ncaused by: " + osErr(err)
		logErrorChain(desc)
		return s.htmlError(req, 400, desc)
	}
	r := newResponse(200)
	r.SetHeader("content-type", "text/plain; charset=utf-8")
	r.Body = []byte(c.formatSize(size))
	return r
}
