					return uploadError(400, "Invalid path\ncaused by: Cannot use '..' in mkdir path")
				}
			}
			for _, comp := range strings.Split(name, "/") {
				if strings.HasPrefix(comp, ".") && comp != "." {
					return uploadError(400, "Invalid path\ncaused by: Cannot use hidden paths in mkdir path")
				}
			}
			newDir := filepath.Join(resolved, name)
			if err := os.MkdirAll(newDir, 0o777); err != nil {
				return uploadError(500, fmt.Sprintf("Failed to create directory\ncaused by: %s", osErr(err)))
			}
			continue
		}
		if !hasFilename {
			return uploadError(400, "Failed to parse HTTP header\ncaused by: Failed to retrieve the name of the file to upload")
		}
		filename := cdParams["filename"]
		fileComps := sanitizeComponents(filename)
		if !c.ShowHidden && hasHiddenComponent(fileComps) {
			return uploadError(400, "Invalid path\ncaused by: Invalid file name to upload")
		}
		dest := resolved
		if len(fileComps) > 0 {
			dest = filepath.Join(append([]string{resolved}, fileComps...)...)
		}
		if _, err := os.Lstat(dest); err == nil {
			switch c.OnDuplicateFiles {
			case "error":
				return uploadError(409, "File already exists, and the on_duplicate_files option is set to error out")
			case "rename":
				dest = renameDuplicate(dest)
			}
		}
		if r := s.saveUploadedFile(part, dest, hasher, expectedHash); r != nil {
			return r
		}
	}
	return s.redirect(303, returnAddress(req))
}

func multipartErrName(err error) string {
	return err.Error()
}

// renameDuplicate finds "name-N.ext" that does not exist yet.
func renameDuplicate(dest string) string {
	dir := filepath.Dir(dest)
	base := filepath.Base(dest)
	stem := base
	ext := ""
	if i := strings.LastIndexByte(base, '.'); i > 0 {
		stem = base[:i]
		ext = base[i:]
	}
	for n := 1; ; n++ {
		cand := filepath.Join(dir, fmt.Sprintf("%s-%d%s", stem, n, ext))
		if _, err := os.Lstat(cand); err != nil {
			return cand
		}
	}
}

func randomTempName() string {
	const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
	b := make([]byte, 6)
	rand.Read(b)
	for i := range b {
		b[i] = chars[int(b[i])%len(chars)]
	}
	return ".tmp" + string(b)
}

func currentUmask() uint32 {
	m := syscall.Umask(0)
	syscall.Umask(m)
	return uint32(m)
}

func (s *Server) saveUploadedFile(part io.Reader, dest string, hasher hash.Hash, expected string) *Response {
	c := s.cfg
	tmpDir := c.TempUploadDir
	if tmpDir == "" {
		tmpDir = os.TempDir()
	}
	tmpPath := filepath.Join(tmpDir, randomTempName())
	f, err := os.OpenFile(tmpPath, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return uploadError(500, fmt.Sprintf("Failed to create temporary file\ncaused by: %s", osErr(err)))
	}
	var w io.Writer = f
	if hasher != nil {
		hasher.Reset()
		w = io.MultiWriter(f, hasher)
	}
	if _, err := io.Copy(w, part); err != nil {
		f.Close()
		os.Remove(tmpPath)
		return uploadError(500, fmt.Sprintf("Failed to save file\ncaused by: %s", osErr(err)))
	}
	f.Close()
	if hasher != nil {
		got := hex.EncodeToString(hasher.Sum(nil))
		if got != expected {
			os.Remove(tmpPath)
			return uploadError(400, "File hash that was provided did not match checksum of uploaded file")
		}
	}
	logInfo(fmt.Sprintf("File upload successful to %q. Moving to %q", tmpPath, dest))
	if err := os.Rename(tmpPath, dest); err != nil {
		if le, ok := err.(*os.LinkError); ok && le.Err == syscall.EXDEV {
			if err2 := copyFile(tmpPath, dest); err2 != nil {
				os.Remove(tmpPath)
				return uploadError(500, fmt.Sprintf("Failed to move temporary file %q to %q\ncaused by: %s", tmpPath, dest, osErr(err2)))
			}
			os.Remove(tmpPath)
		} else {
			os.Remove(tmpPath)
			return uploadError(500, fmt.Sprintf("Failed to move temporary file %q to %q\ncaused by: %s", tmpPath, dest, osErr(err)))
		}
	}
	var mode uint32
	if c.Chmod != nil {
		mode = *c.Chmod
	} else {
		mode = 0o666 &^ currentUmask()
	}
	logInfo(fmt.Sprintf("Changing file mode (chmod) to %o", mode))
	os.Chmod(dest, os.FileMode(mode))
	return nil
}

func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	out, err := os.OpenFile(dst, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600)
	if err != nil {
		return err
	}
	if _, err := io.Copy(out, in); err != nil {
		out.Close()
		return err
	}
	return out.Close()
}

// parseQueryParamsStrict parses the query and returns nil on any error.
func parseQueryParamsStrict(q string) *queryParams {
	var qp queryParams
	seen := map[string]bool{}
	for _, kv := range parseQuery(q) {
		k, v := kv[0], kv[1]
		switch k {
		case "sort", "order", "raw", "download", "path", "mkdir":
			if seen[k] {
				return nil
			}
			seen[k] = true
		}
		switch k {
		case "sort":
			if v != "name" && v != "size" && v != "date" {
				return nil
			}
			qp.sort = v
		case "order":
			if v != "asc" && v != "desc" {
				return nil
			}
			qp.order = v
		case "raw":
			if v == "true" {
				qp.raw = true
			} else if v != "false" {
				return nil
			}
		case "download":
			if v != "tar" && v != "tar_gz" && v != "zip" {
				return nil
			}
			qp.download = v
		case "path":
			qp.path = v
			qp.hasPath = true
		case "mkdir":
			qp.mkdir = v
			qp.hasMkdir = true
		}
	}
	return &qp
}

// handleRm deletes a file or directory.
func (s *Server) handleRm(req *Request) *Response {
	c := s.cfg
	qp := parseQueryParamsStrict(req.RawQuery)
	if qp == nil || !qp.hasPath {
		return s.htmlError(req, 400, "Query deserialize error: missing field `path`")
	}
	comps := sanitizeComponents(qp.path)
	if !c.ShowHidden && hasHiddenComponent(comps) {
		desc := "Invalid path\ncaused by: Invalid value for 'path' parameter"
		logErrorChain(desc)
		return s.htmlError(req, 400, desc)
	}
	target := filepath.Join(append([]string{c.Path}, comps...)...)
	if _, err := os.Lstat(target); err != nil {
		desc := "Invalid HTTP request\ncaused by: Invalid value for 'path' parameter"
		logErrorChain(desc)
		return s.htmlError(req, 400, desc)
	}
	if !isPathAllowed(c.AllowedRmDir, comps) || len(comps) == 0 && len(c.AllowedRmDir) > 0 {
		desc := "Remove not allowed to this directory"
		logErrorChain(desc)
		return s.htmlError(req, 403, desc)
	}
	st, err := os.Lstat(target)
	if err == nil {
		if st.IsDir() {
			err = os.RemoveAll(target)
		} else {
			err = os.Remove(target)
		}
	}
	if err != nil {
		desc := fmt.Sprintf("Failed to remove %s\ncaused by: %s", target, osErr(err))
		logErrorChain(desc)
		return s.htmlError(req, 500, desc)
	}
	return s.redirect(303, returnAddress(req))
}

// handleAPI implements the directory size API.
func (s *Server) handleAPI(req *Request) *Response {
	c := s.cfg
	ct := req.Header.Get("Content-Type")
	mediatype, _, err := mime.ParseMediaType(ct)
	if err != nil || (mediatype != "application/json" && !strings.HasSuffix(mediatype, "+json")) {
		return s.htmlError(req, 400, "Content type error")
	}
	data, _ := io.ReadAll(io.LimitReader(req.Body, 2*1024*1024))
	cmd, arg, jerr := parseAPICommand(data)
	if jerr != "" {
		return s.htmlError(req, 400, "Json deserialize error: "+jerr)
	}
	if cmd != "DirSize" {
		return s.htmlError(req, 400, "Json deserialize error: unknown variant `"+cmd+"`, expected `DirSize`")
	}
	if !c.DirectorySize {
		r := newResponse(200)
		r.SetHeader("content-type", "text/plain; charset=utf-8")
		r.Body = []byte("-")
		return r
	}
	comps := sanitizeComponents(arg)
	target := filepath.Join(append([]string{c.Path}, comps...)...)
	size, err := dirSize(target)
	if err != nil {
		desc := "Invalid path\ncaused by: " + osErr(err)
		logErrorChain(desc)
		return s.htmlError(req, 400, desc)
	}
	r := newResponse(200)
	r.SetHeader("content-type", "text/plain; charset=utf-8")
	r.Body = []byte(c.formatSize(size))
	return r
}
