package main

import (
	"bytes"
	"compress/flate"
	"compress/gzip"
	"io"
	"strconv"
	"strings"
)

// negotiateEncoding picks a content encoding from Accept-Encoding (gzip/deflate supported).
func negotiateEncoding(accept string) string {
	best := ""
	bestQ := 0.0
	for _, part := range strings.Split(accept, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		name := part
		q := 1.0
		if i := strings.IndexByte(part, ';'); i >= 0 {
			name = strings.TrimSpace(part[:i])
			params := part[i+1:]
			for _, p := range strings.Split(params, ";") {
				p = strings.TrimSpace(p)
				if strings.HasPrefix(p, "q=") {
					if v, err := strconv.ParseFloat(p[2:], 64); err == nil {
						q = v
					}
				}
			}
		}
		name = strings.ToLower(name)
		if q <= 0 {
			continue
		}
		pref := 0.0
		switch name {
		case "gzip":
			pref = 0.9
		case "deflate":
			pref = 0.8
		case "*":
			name = "gzip"
			pref = 0.5
		default:
			continue
		}
		score := q*10 + pref
		if score > bestQ {
			bestQ = score
			best = name
		}
	}
	return best
}

// compressResponse applies content encoding to a response when appropriate.
func compressResponse(req *Request, resp *Response) *Response {
	if resp.Status == 304 || resp.Status == 204 || resp.Status < 200 {
		return resp
	}
	if resp.HasHeader("content-encoding") {
		return resp
	}
	enc := negotiateEncoding(req.Header.Get("Accept-Encoding"))
	if enc == "" {
		return resp
	}
	// collect the body
	var body []byte
	switch {
	case resp.Stream != nil:
		var buf bytes.Buffer
		if err := resp.Stream(&buf); err != nil {
			return resp
		}
		body = buf.Bytes()
		resp.Stream = nil
	case resp.BodyReader != nil:
		b, err := io.ReadAll(io.LimitReader(resp.BodyReader, resp.fixedLength))
		if c, ok := resp.BodyReader.(io.Closer); ok {
			c.Close()
		}
		if err != nil {
			return resp
		}
		body = b
		resp.BodyReader = nil
		resp.fixedLength = 0
	default:
		body = resp.Body
	}
	resp.Body = nil
	resp.SetHeader("vary", "accept-encoding")
	resp.SetHeader("content-encoding", enc)
	resp.Stream = func(w io.Writer) error {
		var cw io.WriteCloser
		if enc == "gzip" {
			cw = gzip.NewWriter(w)
		} else {
			fw, _ := flate.NewWriter(w, flate.DefaultCompression)
			cw = fw
		}
		if _, err := cw.Write(body); err != nil {
			return err
		}
		return cw.Close()
	}
	return resp
}
