	"time"
)

// serveArchive streams a tar/tar.gz/zip archive of the directory.
func (s *Server) serveArchive(req *Request, method string, diskPath string, comps []string) *Response {
	c := s.cfg
	enabled := false
	ext := ""
	ct := ""
	switch method {
	case "tar":
		enabled, ext, ct = c.EnableTar, ".tar", "application/tar"
	case "tar_gz":
		enabled, ext, ct = c.EnableTarGz, ".tar.gz", "application/gzip"
	case "zip":
		enabled, ext, ct = c.EnableZip, ".zip", "application/zip"
	}
	if !enabled {
		desc := "Archive creation is disabled."
		logErrorChain(desc)
		return s.htmlError(req, 403, desc)
	}
	dirName := filepath.Base(diskPath)
	r := newResponse(200)
	r.SetHeader("content-type", ct)
	r.SetHeader("content-transfer-encoding", "binary")
	r.SetHeader("content-disposition", fmt.Sprintf("attachment; filename=\"%s%s\"", dirName, ext))
	follow := !c.NoSymlinks
	switch method {
	case "tar":
		r.Stream = func(w io.Writer) error {
			tw := &tarWriter{w: w}
			if err := tw.appendDirAll(dirName, diskPath, follow); err != nil {
				return err
			}
			return tw.finish()
		}
	case "tar_gz":
		r.Stream = func(w io.Writer) error {
			gz := gzip.NewWriter(w)
			gz.Header.ModTime = time.Now()
			gz.Header.OS = 3
			tw := &tarWriter{w: gz}
			if err := tw.appendDirAll(dirName, diskPath, follow); err != nil {
				return err
			}
			if err := tw.finish(); err != nil {
				return err
			}
			return gz.Close()
		}
	case "zip":
		data, err := zipDirectory(diskPath, dirName)
		if err != nil {
			desc := fmt.Sprintf("Failed to create zip archive\ncaused by: %s", osErr(err))
			logErrorChain(desc)
			return s.htmlError(req, 500, desc)
		}
		r.Stream = func(w io.Writer) error {
			_, err := w.Write(data)
			return err
		}
	}
	return r
}

// ---- tar (GNU format like the tar crate) ----

type tarWriter struct {
	w io.Writer
}

func octal(buf []byte, v uint64) {
	// writes v as zero padded octal with a trailing NUL into buf
	s := fmt.Sprintf("%0*o", len(buf)-1, v)
	if len(s) > len(buf)-1 {
		s = s[len(s)-(len(buf)-1):]
	}
	copy(buf, s)
	buf[len(buf)-1] = 0
}

func (t *tarWriter) writeHeader(name string, mode uint32, uid, gid uint32, size int64, mtime int64, typeflag byte, linkname string) error {
	if len(name) > 100 || len(linkname) > 100 {
		// GNU long name / link extension
		if len(name) > 100 {
			if err := t.writeLongEntry(name, 'L'); err != nil {
				return err
			}
			name = name[:100]
		}
		if len(linkname) > 100 {
			if err := t.writeLongEntry(linkname, 'K'); err != nil {
				return err
			}
			linkname = linkname[:100]
		}
	}
	hdr := make([]byte, 512)
	copy(hdr[0:100], name)
	octal(hdr[100:108], uint64(mode))
	octal(hdr[108:116], uint64(uid))
	octal(hdr[116:124], uint64(gid))
	octal(hdr[124:136], uint64(size))
	if mtime < 0 {
		mtime = 0
	}
	octal(hdr[136:148], uint64(mtime))
	hdr[156] = typeflag
	copy(hdr[157:257], linkname)
	copy(hdr[257:265], "ustar  \x00")
	octal(hdr[329:337], 0)
	octal(hdr[337:345], 0)
	// checksum
	for i := 148; i < 156; i++ {
		hdr[i] = ' '
	}
	var sum uint32
	for _, b := range hdr {
		sum += uint32(b)
	}
