// ---- QR code generation (byte/alphanumeric/numeric segments, EC level L) ----

type qrMode int

const (
	modeNumeric qrMode = iota
	modeAlpha
	modeByte
)

type qrSegment struct {
	mode       qrMode
	begin, end int
}

func charClass(c byte) qrMode {
	switch {
	case c >= '0' && c <= '9':
		return modeNumeric
	case c >= 'A' && c <= 'Z':
		return modeAlpha
	case c == ' ' || c == '$' || c == '%' || c == '*' || c == '+' || c == '-' || c == '.' || c == '/' || c == ':':
		return modeAlpha
	default:
		return modeByte
	}
}

// parseSegments splits data into runs of the same character class.
func parseSegments(data []byte) []qrSegment {
	var segs []qrSegment
	if len(data) == 0 {
		return segs
	}
	begin := 0
	cur := charClass(data[0])
	for i := 1; i < len(data); i++ {
		m := charClass(data[i])
		if m != cur {
			segs = append(segs, qrSegment{cur, begin, i})
			begin = i
			cur = m
		}
	}
	segs = append(segs, qrSegment{cur, begin, len(data)})
	return segs
}

func lengthBits(mode qrMode, version int) int {
	switch mode {
	case modeNumeric:
		if version <= 9 {
			return 10
		} else if version <= 26 {
			return 12
		}
		return 14
	case modeAlpha:
		if version <= 9 {
			return 9
		} else if version <= 26 {
			return 11
		}
		return 13
	default:
		if version <= 9 {
			return 8
		}
		return 16
	}
}

func (s qrSegment) encodedLen(version int) int {
	n := s.end - s.begin
	bits := 4 + lengthBits(s.mode, version)
	switch s.mode {
	case modeNumeric:
		bits += (n/3)*10
		switch n % 3 {
		case 1:
			bits += 4
		case 2:
			bits += 7
		}
	case modeAlpha:
		bits += (n/2)*11 + (n%2)*6
	default:
		bits += n * 8
	}
	return bits
}

func modeMax(a, b qrMode) qrMode {
	if a > b {
		return a
	}
	return b
}

// optimizeSegments merges segments greedily like the qrcode crate's Optimizer.
func optimizeSegments(segs []qrSegment, version int) []qrSegment {
	if len(segs) == 0 {
		return nil
	}
	var out []qrSegment
	last := segs[0]
	lastSize := last.encodedLen(version)
	for _, seg := range segs[1:] {
		segSize := seg.encodedLen(version)
		merged := qrSegment{modeMax(last.mode, seg.mode), last.begin, seg.end}
		mergedSize := merged.encodedLen(version)
		if lastSize+segSize >= mergedSize {
			last = merged
			lastSize = mergedSize
		} else {
			out = append(out, last)
			last = seg
			lastSize = segSize
		}
	}
	out = append(out, last)
	return out
}

