}

type bitBuf struct {
	bits []bool
}

func (b *bitBuf) push(v uint32, n int) {
	for i := n - 1; i >= 0; i-- {
		b.bits = append(b.bits, (v>>uint(i))&1 == 1)
	}
}

func alphaValue(c byte) uint32 {
	const table = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:"
	return uint32(strings.IndexByte(table, c))
}

// qrEncode builds the data codewords for level L and returns (version, codewords).
func qrEncode(data []byte) (int, []byte) {
	segs := parseSegments(data)
	for _, vclass := range []int{9, 26, 40} {
		opt := optimizeSegments(segs, vclass)
		total := 0
		for _, s := range opt {
			total += s.encodedLen(vclass)
		}
		if total <= qrDataCodewordsL[vclass]*8 {
			// find min version with capacity
			version := 1
			for version <= 40 && qrDataCodewordsL[version]*8 < total {
				version++
			}
			var bb bitBuf
			for _, s := range opt {
				n := s.end - s.begin
				switch s.mode {
				case modeNumeric:
					bb.push(1, 4)
					bb.push(uint32(n), lengthBits(modeNumeric, version))
					i := s.begin
					for ; i+3 <= s.end; i += 3 {
						v := uint32(data[i]-'0')*100 + uint32(data[i+1]-'0')*10 + uint32(data[i+2]-'0')
						bb.push(v, 10)
					}
					switch s.end - i {
					case 1:
						bb.push(uint32(data[i]-'0'), 4)
					case 2:
						bb.push(uint32(data[i]-'0')*10+uint32(data[i+1]-'0'), 7)
					}
				case modeAlpha:
					bb.push(2, 4)
					bb.push(uint32(n), lengthBits(modeAlpha, version))
					i := s.begin
					for ; i+2 <= s.end; i += 2 {
						bb.push(alphaValue(data[i])*45+alphaValue(data[i+1]), 11)
					}
					if i < s.end {
						bb.push(alphaValue(data[i]), 6)
					}
				default:
					bb.push(4, 4)
					bb.push(uint32(n), lengthBits(modeByte, version))
					for i := s.begin; i < s.end; i++ {
						bb.push(uint32(data[i]), 8)
					}
				}
			}
			capacity := qrDataCodewordsL[version] * 8
			term := 4
			if capacity-len(bb.bits) < term {
				term = capacity - len(bb.bits)
			}
			bb.push(0, term)
			for len(bb.bits)%8 != 0 {
				bb.bits = append(bb.bits, false)
			}
			cw := make([]byte, 0, qrDataCodewordsL[version])
			for i := 0; i < len(bb.bits); i += 8 {
				var v byte
				for j := 0; j < 8; j++ {
					if bb.bits[i+j] {
						v |= 1 << uint(7-j)
					}
				}
				cw = append(cw, v)
			}
			pad := []byte{0xEC, 0x11}
			for i := 0; len(cw) < qrDataCodewordsL[version]; i++ {
				cw = append(cw, pad[i%2])
			}
			return version, cw
		}
	}
	return 0, nil
}

// ---- Reed-Solomon over GF(256) ----

var gfExp [512]byte
var gfLog [256]byte

func init() {
	x := 1
	for i := 0; i < 255; i++ {
		gfExp[i] = byte(x)
		gfLog[x] = byte(i)
		x <<= 1
		if x&0x100 != 0 {
			x ^= 0x11d
		}
	}
	for i := 255; i < 512; i++ {
		gfExp[i] = gfExp[i-255]
	}
}

func gfMul(a, b byte) byte {
	if a == 0 || b == 0 {
		return 0
	}
	return gfExp[int(gfLog[a])+int(gfLog[b])]
}

func rsGenerator(n int) []byte {
	g := []byte{1}
	for i := 0; i < n; i++ {
		ng := make([]byte, len(g)+1)
		for j := range g {
			ng[j] ^= g[j]
			ng[j+1] ^= gfMul(g[j], gfExp[i])
		}
		g = ng
	}
	return g
}

func rsEncode(data []byte, n int) []byte {
	gen := rsGenerator(n)
	rem := make([]byte, n)
	for _, d := range data {
		factor := d ^ rem[0]
		copy(rem, rem[1:])
		rem[n-1] = 0
		for j := 0; j < n; j++ {
			rem[j] ^= gfMul(gen[j+1], factor)
		}
	}
	return rem
}

// qrCodewords interleaves data and EC codewords.
func qrCodewords(version int, data []byte) []byte {
	info := qrECL[version]
	var blocks [][]byte
	var ecs [][]byte
	pos := 0
	for _, g := range info.groups {
		for i := 0; i < g.count; i++ {
			blk := data[pos : pos+g.dataCW]
			pos += g.dataCW
			blocks = append(blocks, blk)
			ecs = append(ecs, rsEncode(blk, info.ecPerBlock))
		}
	}
	var out []byte
	maxLen := 0
	for _, b := range blocks {
		if len(b) > maxLen {
			maxLen = len(b)
		}
	}
	for i := 0; i < maxLen; i++ {
		for _, b := range blocks {
			if i < len(b) {
				out = append(out, b[i])
			}
		}
	}
	for i := 0; i < info.ecPerBlock; i++ {
		for _, e := range ecs {
			out = append(out, e[i])
		}
	}
	return out
}

// ---- matrix ----

type qrMatrix struct {
	size     int
	modules  []bool // dark?
	function []bool // reserved (function pattern) positions
}

func newMatrix(size int) *qrMatrix {
	return &qrMatrix{size: size, modules: make([]bool, size*size), function: make([]bool, size*size)}
}

func (m *qrMatrix) set(x, y int, dark bool) {
	m.modules[y*m.size+x] = dark
	m.function[y*m.size+x] = true
}

func (m *qrMatrix) get(x, y int) bool {
	return m.modules[y*m.size+x]
}

func (m *qrMatrix) drawFinder(x, y int) {
	for dy := -4; dy <= 4; dy++ {
		for dx := -4; dx <= 4; dx++ {
			xx, yy := x+dx, y+dy
			if xx < 0 || yy < 0 || xx >= m.size || yy >= m.size {
				continue
			}
			d := dx
			if dy > d {
				d = dy
			}
			if -dx > d {
				d = -dx
			}
			if -dy > d {
				d = -dy
			}
			m.set(xx, yy, d != 2 && d != 4)
		}
	}
}

func (m *qrMatrix) drawAlignment(x, y int) {
	for dy := -2; dy <= 2; dy++ {
		for dx := -2; dx <= 2; dx++ {
			d := dx
			if dy > d {
				d = dy
			}
			if -dx > d {
				d = -dx
			}
			if -dy > d {
				d = -dy
			}
			m.set(x+dx, y+dy, d != 1)
		}
	}
}

func bchFormat(data uint32) uint32 {
	// BCH(15,5) with generator 0x537
	rem := data
	for i := 0; i < 10; i++ {
		rem = (rem << 1) ^ ((rem >> 9) * 0x537)
	}
	return ((data << 10) | rem) ^ 0x5412
}

func bchVersion(version uint32) uint32 {
	rem := version
	for i := 0; i < 12; i++ {
		rem = (rem << 1) ^ ((rem >> 11) * 0x1F25)
	}
	return (version << 12) | rem
}

func (m *qrMatrix) drawFunctionPatterns(version int) {
	n := m.size
	// timing patterns
	for i := 0; i < n; i++ {
		m.set(6, i, i%2 == 0)
		m.set(i, 6, i%2 == 0)
	}
	m.drawFinder(3, 3)
	m.drawFinder(n-4, 3)
	m.drawFinder(3, n-4)
	// alignment
	al := qrAlignment[version]
	for _, ay := range al {
		for _, ax := range al {
			if (ax == 6 && ay == 6) || (ax == 6 && ay == n-7) || (ax == n-7 && ay == 6) {
				continue
			}
			m.drawAlignment(ax, ay)
		}
	}
	// reserve format info
	m.drawFormat(0)
	// version info
	if version >= 7 {
		bits := bchVersion(uint32(version))
		for i := 0; i < 18; i++ {
			bit := (bits>>uint(i))&1 == 1
			a := n - 11 + i%3
			b := i / 3
			m.set(a, b, bit)
			m.set(b, a, bit)
		}
	}
}

// drawFormat writes the format information for EC level L and the given mask.
func (m *qrMatrix) drawFormat(mask int) {
	n := m.size
	bits := bchFormat(uint32(1<<3) | uint32(mask)) // L = 01
	for i := 0; i <= 5; i++ {
		m.set(8, i, (bits>>uint(i))&1 == 1)
	}
	m.set(8, 7, (bits>>6)&1 == 1)
	m.set(8, 8, (bits>>7)&1 == 1)
	m.set(7, 8, (bits>>8)&1 == 1)
	for i := 9; i < 15; i++ {
		m.set(14-i, 8, (bits>>uint(i))&1 == 1)
	}
	for i := 0; i < 8; i++ {
		m.set(n-1-i, 8, (bits>>uint(i))&1 == 1)
	}
	for i := 8; i < 15; i++ {
		m.set(8, n-15+i, (bits>>uint(i))&1 == 1)
	}
	m.set(8, n-8, true) // dark module
}

func (m *qrMatrix) drawData(cw []byte) {
	n := m.size
	bitIdx := 0
	total := len(cw) * 8
	getBit := func(i int) bool {
		if i >= total {
			return false
		}
		return (cw[i/8]>>uint(7-i%8))&1 == 1
	}
	for right := n - 1; right >= 1; right -= 2 {
		if right == 6 {
			right = 5
		}
		for vert := 0; vert < n; vert++ {
			for j := 0; j < 2; j++ {
				x := right - j
				upward := ((right + 1) & 2) == 0
				y := vert
				if upward {
					y = n - 1 - vert
				}
				if m.function[y*n+x] {
					continue
				}
				m.modules[y*n+x] = getBit(bitIdx)
				bitIdx++
			}
		}
	}
}

func maskBit(mask, x, y int) bool {
	switch mask {
	case 0:
		return (x+y)%2 == 0
	case 1:
		return y%2 == 0
	case 2:
		return x%3 == 0
	case 3:
		return (x+y)%3 == 0
	case 4:
		return (y/2+x/3)%2 == 0
	case 5:
		return (x*y)%2+(x*y)%3 == 0
	case 6:
		return ((x*y)%2+(x*y)%3)%2 == 0
	default:
		return ((x+y)%2+(x*y)%3)%2 == 0
	}
}

func (m *qrMatrix) applyMask(mask int) {
	n := m.size
	for y := 0; y < n; y++ {
		for x := 0; x < n; x++ {
			if !m.function[y*n+x] && maskBit(mask, x, y) {
				m.modules[y*n+x] = !m.modules[y*n+x]
			}
		}
	}
}

func (m *qrMatrix) penalty() int {
	n := m.size
	score := 0
	// rule 1: adjacent same color runs
	for horiz := 0; horiz < 2; horiz++ {
		for i := 0; i < n; i++ {
			run := 1
			var last int = -1
			for j := 0; j <= n; j++ {
				var color int
				if j == n {
					color = -2
				} else if horiz == 0 {
					color = b2i(m.get(j, i))
				} else {
					color = b2i(m.get(i, j))
				}
				if color == last {
					run++
				} else {
					if run >= 5 {
						score += run - 2
					}
					last = color
					run = 1
				}
			}
		}
	}
	// rule 2: 2x2 blocks
	for y := 0; y < n-1; y++ {
		for x := 0; x < n-1; x++ {
			c := m.get(x, y)
			if c == m.get(x+1, y) && c == m.get(x, y+1) && c == m.get(x+1, y+1) {
				score += 3
			}
		}
	}
	// rule 3: finder-like patterns
	pattern := []bool{true, false, true, true, true, false, true}
	for horiz := 0; horiz < 2; horiz++ {
		get := func(k, i int) bool {
			if horiz == 0 {
				return m.get(k, i)
			}
			return m.get(i, k)
		}
		for i := 0; i < n; i++ {
			for j := 0; j <= n-7; j++ {
				match := true
				for k := 0; k < 7; k++ {
					if get(j+k, i) != pattern[k] {
						match = false
						break
					}
				}
				if !match {
					continue
				}
				darkIn := func(from, to int) bool {
					for k := from; k < to; k++ {
						if k >= 0 && k < n && get(k, i) {
							return true
						}
					}
					return false
				}
				if !(darkIn(j-4, j) && darkIn(j+7, j+11)) {
					score += 40
				}
			}
		}
	}
	// rule 4: balance
	dark := 0
	for _, d := range m.modules {
		if d {
			dark++
		}
	}
	ratio := dark * 200 / len(m.modules)
	if ratio >= 100 {
		score += ratio - 100
	} else {
		score += 100 - ratio
	}
	return score
}

func b2i(b bool) int {
	if b {
		return 1
	}
	return 0
}

// qrMatrixFor builds the final QR matrix for the given text.
func qrMatrixFor(text string) *qrMatrix {
	version, data := qrEncode([]byte(text))
	if version == 0 {
		return nil
	}
	cw := qrCodewords(version, data)
	size := version*4 + 17
	base := newMatrix(size)
	base.drawFunctionPatterns(version)
	base.drawData(cw)
	var best *qrMatrix
	bestScore := -1
	for mask := 0; mask < 8; mask++ {
		m := &qrMatrix{size: size, modules: append([]bool(nil), base.modules...), function: append([]bool(nil), base.function...)}
		m.applyMask(mask)
		m.drawFormat(mask)
		s := m.penalty()
		if best == nil || s < bestScore {
			best = m
			bestScore = s
		}
	}
	return best
}

// qrSVG renders the QR code the way miniserve does.
func qrSVG(text string) string {
	m := qrMatrixFor(text)
	if m == nil {
		return ""
	}
	n := m.size
	dim := n + 2
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf(`<svg viewBox="0 0 %d %d" xmlns="http://www.w3.org/2000/svg"><rect width="%dpx" height="%dpx" fill="#ffffff"/><path d="`, dim, dim, dim, dim))
	for y := 0; y < n; y++ {
		for x := 0; x < n; x++ {
			if m.get(x, y) {
				sb.WriteString(fmt.Sprintf("M%d,%dh1v1h-1", x+1, y+1))
			}
		}
	}
	sb.WriteString(`" fill="#000000"/></svg>`)
	return sb.String()
}
