package main

import (
	"fmt"
	"testing"
)

// module identity: color plus whether it's a function module (for "type-sensitive" variants)
func (m *qrMatrix) id(x, y int, typeSens bool) int {
	v := b2i(m.get(x, y))
	if typeSens && m.function[y*m.size+x] {
		v += 2
	}
	return v
}

func adjVariant(m *qrMatrix, typeSens bool) int {
	n := m.size
	score := 0
	for horiz := 0; horiz < 2; horiz++ {
		for i := 0; i < n; i++ {
			run := 1
			last := -1
			for j := 0; j <= n; j++ {
				color := -2
				if j < n {
					if horiz == 0 {
						color = m.id(j, i, typeSens)
					} else {
						color = m.id(i, j, typeSens)
					}
				}
				if color == last {
					run++
				} else {
					if run >= 5 {
						score += run - 2
					}
					last = color
					run = 1
				}
			}
		}
	}
	return score
}

func blockVariant(m *qrMatrix, typeSens bool) int {
	n := m.size
	score := 0
	for y := 0; y < n-1; y++ {
		for x := 0; x < n-1; x++ {
			c := m.id(x, y, typeSens)
			if c == m.id(x+1, y, typeSens) && c == m.id(x, y+1, typeSens) && c == m.id(x+1, y+1, typeSens) {
				score += 3
			}
		}
	}
	return score
}

func finderV(m *qrMatrix, variant int) int {
	n := m.size
	score := 0
	pattern := []bool{true, false, true, true, true, false, true}
	for horiz := 0; horiz < 2; horiz++ {
		get := func(k, i int) bool {
			if horiz == 0 {
				return m.get(k, i)
			}
			return m.get(i, k)
		}
		for i := 0; i < n; i++ {
			for j := 0; j <= n-7; j++ {
				match := true
				for k := 0; k < 7; k++ {
					if get(j+k, i) != pattern[k] {
						match = false
						break
					}
				}
				if !match {
					continue
				}
				lightRun := func(from, to int, oobLight bool) bool {
					for k := from; k < to; k++ {
						if k < 0 || k >= n {
							if !oobLight {
								return false
							}
							continue
						}
						if get(k, i) {
							return false
						}
					}
					return true
				}
				switch variant {
				case 0: // either side light, oob counts as light
					if lightRun(j-4, j, true) || lightRun(j+7, j+11, true) {
						score += 40
					}
				case 1: // either side light, oob not light
					if lightRun(j-4, j, false) || lightRun(j+7, j+11, false) {
						score += 40
					}
				case 2: // both sides light, oob light
					if lightRun(j-4, j, true) && lightRun(j+7, j+11, true) {
						score += 40
					}
				case 3: // both sides, oob not light
					if lightRun(j-4, j, false) && lightRun(j+7, j+11, false) {
						score += 40
					}
				case 4: // plain pattern
					score += 40
				case 5: // none
				}
			}
		}
	}
