}

func balanceV(m *qrMatrix, variant int) int {
	dark := 0
	for _, d := range m.modules {
		if d {
			dark++
		}
	}
	total := len(m.modules)
	switch variant {
	case 0:
		ratio := dark * 200 / total
		if ratio >= 100 {
			return ratio - 100
		}
		return 100 - ratio
	case 1:
		ratio := dark * 200 / total
		d := ratio - 100
		if d < 0 {
			d = -d
		}
		return d * 10
	case 2:
		pct := dark * 100 / total
		d := pct - 50
		if d < 0 {
			d = -d
		}
		return d / 5 * 10
	case 3:
		// ISO with both k values: min(|prev5 - 50|, |next5 - 50|)/5 *10
		pct := dark * 100 / total
		lo := pct / 5 * 5
		hi := lo + 5
		a := lo - 50
		if a < 0 {
			a = -a
		}
		b := hi - 50
		if b < 0 {
			b = -b
		}
		if a < b {
			return a / 5 * 10
		}
		return b / 5 * 10
	case 4:
		return 0
	}
	return 0
}

