// typeMap builds module type ids for a version.
func typeMap(n, version int, sepType, darkType int) []int {
	tm := make([]int, n*n)
	set := func(x, y, t int) {
		if x >= 0 && y >= 0 && x < n && y < n {
			tm[y*n+x] = t
		}
	}
	// timing
	for i := 0; i < n; i++ {
		set(6, i, 2)
		set(i, 6, 2)
	}
	// finders + separators
	for _, c := range [][2]int{{3, 3}, {n - 4, 3}, {3, n - 4}} {
		for dy := -4; dy <= 4; dy++ {
			for dx := -4; dx <= 4; dx++ {
				d := dx
				if dy > d {
					d = dy
				}
				if -dx > d {
					d = -dx
				}
				if -dy > d {
					d = -dy
				}
				if d == 4 {
					set(c[0]+dx, c[1]+dy, sepType)
				} else {
					set(c[0]+dx, c[1]+dy, 1)
				}
			}
		}
	}
	al := qrAlignment[version]
	for _, ay := range al {
		for _, ax := range al {
			if (ax == 6 && ay == 6) || (ax == 6 && ay == n-7) || (ax == n-7 && ay == 6) {
				continue
			}
			for dy := -2; dy <= 2; dy++ {
				for dx := -2; dx <= 2; dx++ {
					set(ax+dx, ay+dy, 3)
				}
			}
		}
	}
	// format
	for i := 0; i < 9; i++ {
		set(8, i, 4)
		set(i, 8, 4)
	}
	for i := 0; i < 8; i++ {
		set(n-1-i, 8, 4)
		set(8, n-1-i, 4)
	}
	set(8, n-8, darkType)
	return tm
}

func idT(m *qrMatrix, tm []int, x, y int) int {
	return b2i(m.get(x, y)) + 2*tm[y*m.size+x]
}

func adjTyped(m *qrMatrix, tm []int) int {
	n := m.size
	score := 0
	for horiz := 0; horiz < 2; horiz++ {
		for i := 0; i < n; i++ {
			run := 1
			last := -1
			for j := 0; j <= n; j++ {
				color := -2
				if j < n {
					if horiz == 0 {
						color = idT(m, tm, j, i)
					} else {
						color = idT(m, tm, i, j)
					}
				}
				if color == last {
					run++
				} else {
					if run >= 5 {
						score += run - 2
					}
					last = color
					run = 1
				}
			}
		}
	}
	return score
}

func blockTyped(m *qrMatrix, tm []int) int {
	n := m.size
	score := 0
	for y := 0; y < n-1; y++ {
		for x := 0; x < n-1; x++ {
			c := idT(m, tm, x, y)
			if c == idT(m, tm, x+1, y) && c == idT(m, tm, x, y+1) && c == idT(m, tm, x+1, y+1) {
				score += 3
			}
		}
	}
	return score
}

func TestQRTypedSearch(t *testing.T) {
	cases := []struct {
		u    string
		want int
	}{{"http://h:1/", 7}, {"http://a/", 0}, {"http://localhost:8080/", 5}, {"http://example.com:12345/", 6}, {"http://127.0.0.1:8435/abcde/", 6}, {"http://127.0.0.1:8441/abcdefghijk/", 5}, {"http://127.0.0.1:8430//", 6}}
	for sepType := 0; sepType < 8; sepType += 1 {
		for darkType := 0; darkType < 8; darkType++ {
			for fv := 0; fv < 10; fv++ {
				for bv := 0; bv < 4; bv++ {
					for _, useT := range []int{1, 2, 3} {
						ok := true
						for _, c := range cases {
							version, data := qrEncode([]byte(c.u))
							cw := qrCodewords(version, data)
							n := version*4 + 17
							base := newMatrix(n)
							base.drawFunctionPatterns(version)
							base.drawData(cw)
							tm := typeMap(n, version, sepType, darkType)
							best, bestS := -1, 0
							for mask := 0; mask < 8; mask++ {
								m := buildModeMatrix(base, mask, 1)
								a := adjVariant(m, false)
								b := blockVariant(m, false)
								if useT&1 == 1 {
									a = adjTyped(m, tm)
								}
								if useT&2 == 2 {
									b = blockTyped(m, tm)
								}
								s := a + b + finderV(m, fv) + balanceV(m, bv)
								if best < 0 || s < bestS {
									best, bestS = mask, s
								}
							}
							if best != c.want {
								ok = false
								break
							}
						}
						if ok {
							fmt.Println("MATCH sep", sepType, "dark", darkType, "fv", fv, "bv", bv, "useT", useT)
						}
					}
				}
			}
		}
	}
	fmt.Println("done")
}
