func (m *qrMatrix) drawFormatEC(mask int, ec uint32) {
	n := m.size
	bits := bchFormat(ec<<3 | uint32(mask))
	for i := 0; i <= 5; i++ {
		m.set(8, i, (bits>>uint(i))&1 == 1)
	}
	m.set(8, 7, (bits>>6)&1 == 1)
	m.set(8, 8, (bits>>7)&1 == 1)
	m.set(7, 8, (bits>>8)&1 == 1)
	for i := 9; i < 15; i++ {
		m.set(14-i, 8, (bits>>uint(i))&1 == 1)
	}
	for i := 0; i < 8; i++ {
		m.set(n-1-i, 8, (bits>>uint(i))&1 == 1)
	}
	for i := 8; i < 15; i++ {
		m.set(8, n-15+i, (bits>>uint(i))&1 == 1)
	}
	m.set(8, n-8, true)
}

