// finderCarry: 11-bit sliding buffer carried across lines (no reset), guard variants
func finderCarry(m *qrMatrix, resetPerLine bool, guard bool) int {
	n := m.size
	score := 0
	for orient := 0; orient < 2; orient++ {
		buf := 0
		for i := 0; i < n; i++ {
			if resetPerLine {
				buf = 0
			}
			for j := 0; j < n; j++ {
				var v bool
				if orient == 0 {
					v = m.get(j, i)
				} else {
					v = m.get(i, j)
				}
				buf = ((buf << 1) | b2i(v)) & 0x7FF
				if guard && j < 10 {
					continue
				}
				if buf == 0b10111010000 || buf == 0b00001011101 {
					score += 40
				}
			}
		}
	}
	return score
}

func TestQRCarry(t *testing.T) {
	cases := []struct {
		u    string
		want int
	}{{"http://h:1/", 7}, {"http://a/", 0}, {"http://localhost:8080/", 5}, {"http://example.com:12345/", 6}, {"http://127.0.0.1:8435/abcde/", 6}, {"http://127.0.0.1:8441/abcdefghijk/", 5}, {"http://127.0.0.1:8430//", 6}}
