						for mask := 0; mask < 8; mask++ {
							m := buildModeMatrix(base, mask, mode)
							s := adjVariant(m, false) + blockVariant(m, false) + finderCarry(m, reset, guard) + balanceV(m, bv)
							if best < 0 || s < bestS {
								best, bestS = mask, s
							}
						}
						if best != c.want {
							ok = false
							break
						}
					}
					if ok {
						fmt.Println("MATCH reset", reset, "guard", guard, "bv", bv, "mode", mode)
					}
				}
			}
		}
	}
	fmt.Println("done")
}
