		c++
	}
	if core && f.rh[6] >= n*4 && f.rh[0] >= n {
		c++
	}
	return c
}

func (f *finderPenalty) terminateAndCount(color bool, run int) int {
	if color {
		f.addHistory(run)
		run = 0
	}
	run += f.size
	f.addHistory(run)
	return f.countPatterns()
}

func nayukiPenalty(m *qrMatrix) int {
	size := m.size
	result := 0
	for orient := 0; orient < 2; orient++ {
		for y := 0; y < size; y++ {
			runColor := false
			runX := 0
			fp := &finderPenalty{size: size}
			for x := 0; x < size; x++ {
				var mod bool
				if orient == 0 {
					mod = m.get(x, y)
				} else {
					mod = m.get(y, x)
				}
				if mod == runColor {
					runX++
					if runX == 5 {
						result += 3
					} else if runX > 5 {
						result++
					}
				} else {
					fp.addHistory(runX)
					if !runColor {
						result += fp.countPatterns() * 40
					}
					runColor = mod
					runX = 1
				}
			}
			result += fp.terminateAndCount(runColor, runX) * 40
		}
	}
	for y := 0; y < size-1; y++ {
		for x := 0; x < size-1; x++ {
			c := m.get(x, y)
			if c == m.get(x+1, y) && c == m.get(x, y+1) && c == m.get(x+1, y+1) {
