// padded scoring: matrix embedded in a W x W light canvas
func paddedScore(m *qrMatrix, W int, rule1, rule2, rule3 bool, balTotalFull bool, balVariant int, rowsOnlyPadded bool) int {
	n := m.size
	get := func(x, y int) bool {
		if x < n && y < n {
			return m.get(x, y)
		}
		return false
	}
	score := 0
	// rule 1 + 3 per line
	lineScore := func(vals []bool) int {
		s := 0
		buf := 0
		count := 0
		last := vals[0]
		for i, v := range vals {
			buf = ((buf << 1) | b2i(v)) & 0x7FF
			if rule3 && i >= 10 && (buf == 0b10111010000 || buf == 0b00001011101) {
				s += 40
			}
			if v == last {
				count++
			} else {
				if rule1 && count >= 5 {
					s += count - 2
				}
				count = 1
				last = v
