{"command":"cd /workspace && cat > markdown.go <<'EOF'
package main

import (
	"fmt"
	"html"
	"regexp"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// A reasonably complete CommonMark renderer producing comrak-like HTML output
// (raw HTML is replaced by "<!-- raw HTML omitted -->").

type mdBlock struct {
	kind     string // paragraph, heading, code, fenced, html, quote, list, item, hr
	level    int
	lines    []string
	children []*mdBlock
	info     string
	// list info
	ordered  bool
	start    int
	bullet   byte
	delim    byte
	tight    bool
	indent   int // content indent for list items
	open     bool
	fence    string
	fenceInd int
	lastBlank bool
	hasBlankInside bool
}

type mdParser struct {
	root   *mdBlock
	refs   map[string]mdRef
	lines  []string
}

type mdRef struct {
	dest, title string
}

func renderMarkdown(src string) string {
	src = strings.ReplaceAll(src, "\r\n", "\n")
	src = strings.ReplaceAll(src, "\r", "\n")
	src = strings.ReplaceAll(src, "\x00", "\uFFFD")
	p := &mdParser{root: &mdBlock{kind: "document", open: true}, refs: map[string]mdRef{}}
	lines := strings.Split(src, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	p.lines = lines
	for _, line := range lines {
		p.addLine(expandTabs(line))
	}
	p.closeAll(p.root)
	p.extractRefs(p.root)
	var sb strings.Builder
	p.renderBlocks(&sb, p.root.children, false)
	return sb.String()
}

func expandTabs(line string) string {
	if !strings.Contains(line, "\t") {
		return line
	}
	var sb strings.Builder
	col := 0
	for _, r := range line {
		if r == '\t' {
			n := 4 - col%4
			sb.WriteString(strings.Repeat(" ", n))
			col += n
		} else {
			sb.WriteRune(r)
			col++
		}
	}
	return sb.String()
}

func indentOf(s string) int {
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

func isBlank(s string) bool {
	return strings.TrimSpace(s) == ""
}

var atxRe = regexp.MustCompile(`^ {0,3}(#{1,6})(?:[ \t]+(.*?))?(?:[ \t]+#+)?[ \t]*$`)
var atxReSimple = regexp.MustCompile(`^ {0,3}(#{1,6})(?:[ \t]+|$)`)
var hrRe = regexp.MustCompile(`^ {0,3}((\*[ \t]*){3,}|(-[ \t]*){3,}|(_[ \t]*){3,})[ \t]*$`)
var fenceRe = regexp.MustCompile("^( {0,3})(`{3,}|~{3,})(.*)$")
var bulletRe = regexp.MustCompile(`^( {0,3})([-+*])( +|$)(.*)$`)
var orderedRe = regexp.MustCompile(`^( {0,3})(\d{1,9})([.)])( +|$)(.*)$`)
var setextRe = regexp.MustCompile(`^ {0,3}(=+|-+)[ \t]*$`)
var htmlBlockStartRe = regexp.MustCompile(`^ {0,3}<(?:/?(?:address|article|aside|base|basefont|blockquote|body|caption|center|col|colgroup|dd|details|dialog|dir|div|dl|dt|fieldset|figcaption|figure|footer|form|frame|frameset|h1|h2|h3|h4|h5|h6|head|header|hr|html|iframe|legend|li|link|main|menu|menuitem|nav|noframes|ol|optgroup|option|p|param|section|source|summary|table|tbody|td|tfoot|th|thead|title|tr|track|ul)(?:[ \t>]|/>|$)|(?:script|pre|style|textarea)(?:[ \t>]|$)|!--|\?|![A-Za-z]|!\[CDATA\[|(?:[A-Za-z][A-Za-z0-9-]*)(?:\s+[A-Za-z_:][A-Za-z0-9_.:-]*(?:\s*=\s*(?:[^\s"'=<>` + "`" + `]+|'[^']*'|"[^"]*"))?)*\s*/?>\s*$|/[A-Za-z][A-Za-z0-9-]*\s*>\s*$)`)

// lastOpenChild returns the deepest open container chain.
func (p *mdParser) addLine(line string) {
	// Walk open containers, matching continuation markers.
	container := p.root
	rest := line
	var chain []*mdBlock
	chain = append(chain, p.root)
	allMatched := true
	for {
		var next *mdBlock
		if len(container.children) > 0 {
			last := container.children[len(container.children)-1]
			if last.open && (last.kind == "quote" || last.kind == "item" || last.kind == "list") {
				next = last
			}
		}
		if next == nil {
			break
		}
		switch next.kind {
		case "quote":
			ind := indentOf(rest)
			if ind <= 3 && ind < len(rest) && rest[ind] == '>' {
				rest = rest[ind+1:]
				if strings.HasPrefix(rest, " ") {
					rest = rest[1:]
				}
			} else {
				allMatched = false
			}
		case "list":
			// lists are transparent; continue to the item
		case "item":
			if isBlank(rest) {
				// blank line continues the item (unless the item is empty and just started)
				if len(next.children) == 0 && next.lastBlank {
					allMatched = false
				}
			} else if indentOf(rest) >= next.indent {
				rest = rest[next.indent:]
			} else {
				allMatched = false
			}
		}
		if !allMatched {
			break
		}
		chain = append(chain, next)
		container = next
	}
	// Now container is the deepest matched container; check for lazy continuation
	// and new block starts.
	p.processRest(container, chain, rest, line, allMatched)
}

func (p *mdParser) lastChild(b *mdBlock) *mdBlock {
	if len(b.children) == 0 {
		return nil
	}
	return b.children[len(b.children)-1]
}

func (p *mdParser) closeAll(b *mdBlock) {
	b.open = false
	for _, c := range b.children {
		if c.open {
			p.closeAll(c)
		}
	}
	if b.kind == "paragraph" {
		// trim
	}
}

func (p *mdParser) closeLastChild(b *mdBlock) {
	if lc := p.lastChild(b); lc != nil && lc.open {
		p.closeAll(lc)
	}
}

// processRest handles the remainder of the line after container markers.
func (p *mdParser) processRest(container *mdBlock, chain []*mdBlock, rest string, fullLine string, allMatched bool) {
	// an open fenced code block or indented code or html block in the deepest container?
	last := p.lastChild(container)
	if allMatched && last != nil && last.open {
		switch last.kind {
		case "fenced":
			ind := indentOf(rest)
			if ind <= 3 {
				t := strings.TrimRight(rest[ind:], " \t")
				if strings.HasPrefix(t, last.fence) && strings.Trim(t, string(last.fence[0])) == "" {
					last.open = false
					return
				}
			}
			// strip up to fenceInd spaces
			strip := last.fenceInd
			if indentOf(rest) < strip {
				strip = indentOf(rest)
			}
			last.lines = append(last.lines, rest[strip:])
			return
		case "html":
			last.lines = append(last.lines, rest)
			if htmlBlockEnds(last, rest) {
				last.open = false
			}
			return
		case "code":
			if indentOf(rest) >= 4 {
				last.lines = append(last.lines, rest[4:])
				return
			}
			if isBlank(rest) {
				last.lines = append(last.lines, "")
				return
			}
			last.open = false
		}
	}
	if !allMatched {
		// lazy paragraph continuation?
		deepest := p.deepestOpenLeaf(p.root)
		if deepest != nil && deepest.kind == "paragraph" && !isBlank(rest) && !p.startsBlock(rest) {
			deepest.lines = append(deepest.lines, strings.TrimLeft(rest, " "))
			return
		}
		// close unmatched containers
		p.closeAll(chain[len(chain)-1].lastOpenContainerChild())
		// re-walk: the deepest matched container is chain[len-1]
	}
	// mark blank handling for items
	if isBlank(rest) {
		if last != nil && last.open && last.kind == "paragraph" {
			last.open = false
		}
		if container.kind == "item" {
			if len(container.children) == 0 {
				container.lastBlank = true
			} else {
				container.hasBlankInside = true
			}
		}
		// blank line inside a list: mark potential looseness
		for _, c := range chain {
			if c.kind == "item" && len(c.children) > 0 {
				c.lastBlank = true
			}
		}
		if last != nil && last.kind == "list" && !last.open {
			// nothing
		}
		return
	}
	p.openBlock(container, rest)
}

func (b *mdBlock) lastOpenContainerChild() *mdBlock {
	if len(b.children) == 0 {
		return b
	}
	last := b.children[len(b.children)-1]
	if last.open {
		return last
	}
	return b
}

func (p *mdParser) deepestOpenLeaf(b *mdBlock) *mdBlock {
	for {
		last := p.lastChild(b)
		if last == nil || !last.open {
			return b
		}
		b = last
	}
}

// startsBlock reports whether the text would start a new block (interrupting a paragraph).
func (p *mdParser) startsBlock(rest string) bool {
	ind := indentOf(rest)
	if ind >= 4 {
		return false
	}
	t := rest[ind:]
	if strings.HasPrefix(t, ">") {
		return true
	}
	if atxReSimple.MatchString(rest) {
		return true
	}
	if hrRe.MatchString(rest) {
		return true
	}
	if fenceRe.MatchString(rest) {
		return true
	}
	if m := bulletRe.FindStringSubmatch(rest); m != nil && !isBlank(m[4]) {
		return true
	}
	if m := orderedRe.FindStringSubmatch(rest); m != nil && m[2] == "1" && !isBlank(m[5]) {
		return true
	}
	if htmlBlockStartRe.MatchString(rest) && !strings.HasPrefix(strings.TrimLeft(rest, " "), "<pre") {
		return true
	}
	return false
}

// openBlock creates a new block for the content in the given container.
func (p *mdParser) openBlock(container *mdBlock, rest string) {
	ind := indentOf(rest)
	last := p.lastChild(container)
	// indented code
	if ind >= 4 {
		if last != nil && last.open && last.kind == "paragraph" {
			last.lines = append(last.lines, strings.TrimLeft(rest, " "))
			return
		}
		p.closeLastChild(container)
		container.children = append(container.children, &mdBlock{kind: "code", open: true, lines: []string{rest[4:]}})
		return
	}
	t := rest[ind:]
	// blockquote
	if strings.HasPrefix(t, ">") {
		p.closeLastChild(container)
		q := &mdBlock{kind: "quote", open: true}
		container.children = append(container.children, q)
		inner := t[1:]
		if strings.HasPrefix(inner, " ") {
			inner = inner[1:]
		}
		if isBlank(inner) {
			return
		}
		p.openBlock(q, inner)
		return
	}
	// ATX heading
	if m := atxRe.FindStringSubmatch(rest); m != nil {
		p.closeLastChild(container)
		content := strings.TrimSpace(m[2])
		// remove closing sequence
		content = strings.TrimRight(content, " \t")
		if i := strings.LastIndex(content, " #"); i >= 0 && strings.Trim(content[i+1:], "#") == "" {
			content = strings.TrimRight(content[:i], " \t")
		} else if strings.Trim(content, "#") == "" {
			content = ""
		}
		container.children = append(container.children, &mdBlock{kind: "heading", level: len(m[1]), lines: []string{content}})
		return
	}
	// fenced code
	if m := fenceRe.FindStringSubmatch(rest); m != nil {
		info := strings.TrimSpace(m[3])
		if !(m[2][0] == '`' && strings.Contains(info, "`")) {
			p.closeLastChild(container)
			container.children = append(container.children, &mdBlock{kind: "fenced", open: true, fence: m[2], fenceInd: len(m[1]), info: info})
			return
		}
	}
	// html block
	if htmlBlockStartRe.MatchString(rest) {
		if !(last != nil && last.open && last.kind == "paragraph" && htmlBlockKind(rest) == 7) {
			p.closeLastChild(container)
			b := &mdBlock{kind: "html", open: true, level: htmlBlockKind(rest), lines: []string{rest}}
			container.children = append(container.children, b)
			if htmlBlockEnds(b, rest) {
				b.open = false
			}
			return
		}
	}
	// setext heading
	if last != nil && last.open && last.kind == "paragraph" && setextRe.MatchString(rest) {
		level := 2
		if strings.Contains(rest, "=") {
			level = 1
		}
		last.kind = "heading"
		last.level = level
		last.open = false
		last.lines = []string{strings.Join(last.lines, "\n")}
		return
	}
	// thematic break
	if hrRe.MatchString(rest) {
		p.closeLastChild(container)
		container.children = append(container.children, &mdBlock{kind: "hr"})
		return
	}
	// list items
	if m := bulletRe.FindStringSubmatch(rest); m != nil {
		if last != nil && last.open && last.kind == "paragraph" && isBlank(m[4]) {
			// empty bullet can't interrupt a paragraph
		} else {
			p.startListItem(container, false, 0, m[2][0], 0, len(m[1]), len(m[2]), m[3], m[4])
			return
		}
	}
	if m := orderedRe.FindStringSubmatch(rest); m != nil {
		start, _ := strconv.Atoi(m[2])
		if last != nil && last.open && last.kind == "paragraph" && (start != 1 || isBlank(m[5])) {
			// can't interrupt
		} else {
			p.startListItem(container, true, start, 0, m[3][0], len(m[1]), len(m[2])+1, m[4], m[5])
			return
		}
	}
	// paragraph
	if last != nil && last.open && last.kind == "paragraph" {
		last.lines = append(last.lines, strings.TrimLeft(rest, " "))
		return
	}
	p.closeLastChild(container)
	container.children = append(container.children, &mdBlock{kind: "paragraph", open: true, lines: []string{strings.TrimLeft(rest, " ")}})
}

func (p *mdParser) startListItem(container *mdBlock, ordered bool, start int, bullet byte, delim byte, leading int, markerLen int, spaces string, content string) {
	spaceCount := len(spaces)
	contentIndent := leading + markerLen + spaceCount
	if spaceCount == 0 || spaceCount > 4 || isBlank(content) {
		// content starts with code block or is empty: indent = marker + 1
		if spaceCount > 4 {
			content = strings.Repeat(" ", spaceCount-1) + content
		}
		contentIndent = leading + markerLen + 1
	}
	last := p.lastChild(container)
	var list *mdBlock
	if last != nil && last.open && last.kind == "list" && last.ordered == ordered && last.bullet == bullet && last.delim == delim {
		list = last
	} else {
		p.closeLastChild(container)
		list = &mdBlock{kind: "list", open: true, ordered: ordered, start: start, bullet: bullet, delim: delim, tight: true}
		container.children = append(container.children, list)
	}
	// close previous item
	if li := p.lastChild(list); li != nil && li.open {
		p.closeAll(li)
	}
	item := &mdBlock{kind: "item", open: true, indent: contentIndent}
	list.children = append(list.children, item)
	if isBlank(content) {
		item.lastBlank = true
		return
	}
	p.openBlock(item, content)
}

func htmlBlockKind(line string) int {
	t := strings.TrimLeft(line, " ")
	lower := strings.ToLower(t)
	switch {
	case strings.HasPrefix(lower, "<script"), strings.HasPrefix(lower, "<pre"), strings.HasPrefix(lower, "<style"), strings.HasPrefix(lower, "<textarea"):
		return 1
	case strings.HasPrefix(t, "<!--"):
		return 2
	case strings.HasPrefix(t, "<?"):
		return 3
	case strings.HasPrefix(t, "<![CDATA["):
		return 5
	case strings.HasPrefix(t, "<!"):
		return 4
	}
	if regexp.MustCompile(`^</?(?i:address|article|aside|base|basefont|blockquote|body|caption|center|col|colgroup|dd|details|dialog|dir|div|dl|dt|fieldset|figcaption|figure|footer|form|frame|frameset|h1|h2|h3|h4|h5|h6|head|header|hr|html|iframe|legend|li|link|main|menu|menuitem|nav|noframes|ol|optgroup|option|p|param|section|source|summary|table|tbody|td|tfoot|th|thead|title|tr|track|ul)(?:[ \t>]|/>|$)`).MatchString(t) {
		return 6
	}
	return 7
}

func htmlBlockEnds(b *mdBlock, line string) bool {
	lower := strings.ToLower(line)
	switch b.level {
	case 1:
		return strings.Contains(lower, "</script>") || strings.Contains(lower, "</pre>") || strings.Contains(lower, "</style>") || strings.Contains(lower, "</textarea>")
	case 2:
		return strings.Contains(line, "-->")
	case 3:
		return strings.Contains(line, "?>")
	case 4:
		return strings.Contains(line, ">")
	case 5:
		return strings.Contains(line, "]]>")
	default:
		return isBlank(line)
	}
}

var refDefRe = regexp.MustCompile(`^ {0,3}\[((?:[^\]\\]|\\.){1,999})\]:[ \t]*(?:\n[ \t]*)?(<[^>\n]*>|[^\s<][^\s]*)(?:(?:[ \t]+|[ \t]*\n[ \t]*)("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\((?:[^)\\]|\\.)*\)))?[ \t]*(?:\n|$)`)

// extractRefs pulls link reference definitions out of paragraphs.
func (p *mdParser) extractRefs(b *mdBlock) {
	var kept []*mdBlock
	for _, c := range b.children {
		if c.kind == "paragraph" {
			text := strings.Join(c.lines, "\n")
			for {
				m := refDefRe.FindStringSubmatch(text)
				if m == nil {
					break
				}
				label := normalizeLabel(m[1])
				dest := m[2]
				if strings.HasPrefix(dest, "<") {
					dest = dest[1 : len(dest)-1]
				}
				title := ""
				if m[3] != "" {
					title = m[3][1 : len(m[3])-1]
				}
				if _, exists := p.refs[label]; !exists && label != "" {
					p.refs[label] = mdRef{unescapeMd(dest), unescapeMd(title)}
				}
				text = text[len(m[0]):]
			}
			if strings.TrimSpace(text) == "" {
				continue
			}
			c.lines = strings.Split(text, "\n")
		}
		p.extractRefs(c)
		kept = append(kept, c)
	}
	b.children = kept
}

func normalizeLabel(s string) string {
	s = strings.TrimSpace(s)
	s = regexp.MustCompile(`\s+`).ReplaceAllString(s, " ")
	return strings.ToLower(s)
}

func unescapeMd(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) && isASCIIPunct(s[i+1]) {
			sb.WriteByte(s[i+1])
			i++
			continue
		}
		sb.WriteByte(s[i])
	}
	return decodeEntities(sb.String())
}

func isASCIIPunct(c byte) bool {
	return c >= 33 && c <= 47 || c >= 58 && c <= 64 || c >= 91 && c <= 96 || c >= 123 && c <= 126
}

var entityRe = regexp.MustCompile(`&(?:#[xX][0-9a-fA-F]{1,6}|#[0-9]{1,7}|[A-Za-z][A-Za-z0-9]{1,31});`)

func decodeEntities(s string) string {
	return entityRe.ReplaceAllStringFunc(s, func(m string) string {
		u := html.UnescapeString(m)
		if u == m {
			return m
		}
		if u == "\x00" {
			return "\uFFFD"
		}
		return u
	})
}

// ---- rendering ----

func mdEscape(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '&':
			sb.WriteString("&amp;")
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		case '"':
			sb.WriteString("&quot;")
		default:
			sb.WriteByte(s[i])
		}
	}
	return sb.String()
}

func mdEscapeHref(s string) string {
	const hexd = "0123456789ABCDEF"
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '&':
			sb.WriteString("&amp;")
		case c == '\'':
			sb.WriteString("&#x27;")
		case c < 0x20 || c >= 0x7f || c == ' ' || c == '"' || c == '<' || c == '>' || c == '`' || c == '[' || c == ']' || c == '\\' || c == '^' || c == '{' || c == '}' || c == '|':
			sb.WriteByte('%')
			sb.WriteByte(hexd[c>>4])
			sb.WriteByte(hexd[c&15])
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

func (p *mdParser) listIsTight(list *mdBlock) bool {
	for i, item := range list.children {
		if item.hasBlankInside {
			return false
		}
		// blank line between items
		if i < len(list.children)-1 && item.lastBlank {
			return false
		}
		// nested blank lines between child blocks
		for j, c := range item.children {
			if j < len(item.children)-1 && c.lastBlank {
				return false
			}
		}
	}
	return true
}

func (p *mdParser) renderBlocks(sb *strings.Builder, blocks []*mdBlock, tight bool) {
	for _, b := range blocks {
		switch b.kind {
		case "paragraph":
			text := strings.Join(b.lines, "\n")
			if tight {
				sb.WriteString(p.renderInline(text))
				sb.WriteString("\n")
			} else {
				sb.WriteString("<p>" + p.renderInline(text) + "</p>\n")
			}
		case "heading":
			sb.WriteString(fmt.Sprintf("<h%d>%s</h%d>\n", b.level, p.renderInline(strings.TrimSpace(strings.Join(b.lines, "\n"))), b.level))
		case "code":
			// strip trailing blank lines
			lines := b.lines
			for len(lines) > 0 && isBlank(lines[len(lines)-1]) {
				lines = lines[:len(lines)-1]
			}
			sb.WriteString("<pre><code>" + mdEscape(strings.Join(lines, "\n")+"\n") + "</code></pre>\n")
		case "fenced":
			cls := ""
			if b.info != "" {
				lang := strings.Fields(unescapeMd(b.info))[0]
				cls = ` class="language-` + mdEscape(lang) + `"`
			}
			content := ""
			if len(b.lines) > 0 {
				content = strings.Join(b.lines, "\n") + "\n"
			}
			sb.WriteString("<pre><code" + cls + ">" + mdEscape(content) + "</code></pre>\n")
		case "html":
			sb.WriteString("<!-- raw HTML omitted -->\n")
		case "hr":
			sb.WriteString("<hr />\n")
		case "quote":
			sb.WriteString("<blockquote>\n")
			p.renderBlocks(sb, b.children, false)
			sb.WriteString("</blockquote>\n")
		case "list":
			tightList := p.listIsTight(b)
			if b.ordered {
				if b.start != 1 {
					sb.WriteString(fmt.Sprintf("<ol start=\"%d\">\n", b.start))
				} else {
					sb.WriteString("<ol>\n")
				}
			} else {
				sb.WriteString("<ul>\n")
			}
			for _, item := range b.children {
				sb.WriteString("<li>")
				if len(item.children) > 0 {
					first := item.children[0]
					if tightList && first.kind == "paragraph" {
						// inline rendering without <p>
						var inner strings.Builder
						p.renderBlocks(&inner, item.children, true)
						s := inner.String()
						s = strings.TrimSuffix(s, "\n")
						sb.WriteString(s)
					} else {
						sb.WriteString("\n")
						p.renderBlocks(sb, item.children, tightList)
					}
				}
				sb.WriteString("</li>\n")
			}
			if b.ordered {
				sb.WriteString("</ol>\n")
			} else {
				sb.WriteString("</ul>\n")
			}
		case "item":
			p.renderBlocks(sb, b.children, tight)
		}
	}
}

// ---- inline parsing ----

type delim struct {
	pos       int // index into nodes
	ch        byte
	count     int
	canOpen   bool
	canClose  bool
	origCount int
	active    bool
}

type inlineNode struct {
	kind string // text, code, html, br, softbreak, link, image, em, strong, delim, raw
	text string
	dest string
	title string
	children []*inlineNode
}

func (p *mdParser) renderInline(text string) string {
	nodes := p.parseInlines(text)
	var sb strings.Builder
	renderNodes(&sb, nodes)
	return sb.String()
}

func renderNodes(sb *strings.Builder, nodes []*inlineNode) {
	for _, n := range nodes {
		switch n.kind {
		case "text":
			sb.WriteString(mdEscape(n.text))
		case "raw":
			sb.WriteString(n.text)
		case "code":
			sb.WriteString("<code>" + mdEscape(n.text) + "</code>")
		case "html":
			sb.WriteString("<!-- raw HTML omitted -->")
		case "br":
			sb.WriteString("<br />\n")
		case "softbreak":
			sb.WriteString("\n")
		case "em":
			sb.WriteString("<em>")
			renderNodes(sb, n.children)
			sb.WriteString("</em>")
		case "strong":
			sb.WriteString("<strong>")
			renderNodes(sb, n.children)
			sb.WriteString("</strong>")
		case "link":
			sb.WriteString(`<a href="` + mdEscapeHref(n.dest) + `"`)
			if n.title != "" {
				sb.WriteString(` title="` + mdEscape(n.title) + `"`)
			}
			sb.WriteString(">")
			renderNodes(sb, n.children)
			sb.WriteString("</a>")
		case "image":
			sb.WriteString(`<img src="` + mdEscapeHref(n.dest) + `" alt="`)
			var alt strings.Builder
			renderAlt(&alt, n.children)
			sb.WriteString(mdEscape(alt.String()) + `"`)
			if n.title != "" {
				sb.WriteString(` title="` + mdEscape(n.title) + `"`)
			}
			sb.WriteString(" />")
		}
	}
}

func renderAlt(sb *strings.Builder, nodes []*inlineNode) {
	for _, n := range nodes {
		switch n.kind {
		case "text", "code":
			sb.WriteString(n.text)
		case "softbreak", "br":
			sb.WriteString("\n")
		default:
			renderAlt(sb, n.children)
		}
	}
}

var autolinkRe = regexp.MustCompile(`^<([A-Za-z][A-Za-z0-9+.-]{1,31}:[^\s<>]*)>`)
var emailAutolinkRe = regexp.MustCompile(`^<([a-zA-Z0-9.!#$%&'*+/=?^_` + "`" + `{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*)>`)
var inlineHTMLRe = regexp.MustCompile(`^(?:<[A-Za-z][A-Za-z0-9-]*(?:\s+[A-Za-z_:][A-Za-z0-9_.:-]*(?:\s*=\s*(?:[^\s"'=<>` + "`" + `]+|'[^']*'|"[^"]*"))?)*\s*/?>|</[A-Za-z][A-Za-z0-9-]*\s*>|<!--(?:[^-]|-[^-])*-->|<\?[\s\S]*?\?>|<![A-Za-z]+\s+[^>]*>|<!\[CDATA\[[\s\S]*?\]\]>)`)

type inlineParser struct {
	p      *mdParser
	s      string
	pos    int
	nodes  []*inlineNode
	delims []*delim
	brackets []*bracket
}

type bracket struct {
	nodeIdx int
	image   bool
	active  bool
	delimLen int
}

func (p *mdParser) parseInlines(text string) []*inlineNode {
	ip := &inlineParser{p: p, s: text}
	ip.run()
	ip.processEmphasis(-1)
	// merge adjacent text nodes
	return mergeText(ip.nodes)
}

func mergeText(nodes []*inlineNode) []*inlineNode {
	var out []*inlineNode
	for _, n := range nodes {
		if n.kind == "delim" {
			n = &inlineNode{kind: "text", text: n.text}
		}
		if n.kind == "text" && len(out) > 0 && out[len(out)-1].kind == "text" {
			out[len(out)-1].text += n.text
			continue
		}
		if len(n.children) > 0 {
			n.children = mergeText(n.children)
		}
		out = append(out, n)
	}
	return out
}

func (ip *inlineParser) addText(t string) {
	ip.nodes = append(ip.nodes, &inlineNode{kind: "text", text: t})
}

func isUnicodeWhitespace(r rune) bool {
	return r == -1 || unicode.IsSpace(r) || r == 0
}

func isPunct(r rune) bool {
	return r < 128 && isASCIIPunct(byte(r)) || unicode.IsPunct(r) || unicode.IsSymbol(r)
}

func (ip *inlineParser) run() {
	s := ip.s
	var textStart int = -1
	flushText := func(end int) {
		if textStart >= 0 && end > textStart {
			ip.addText(s[textStart:end])
		}
		textStart = -1
	}
	for ip.pos < len(s) {
		c := s[ip.pos]
		switch c {
		case '\\':
			if ip.pos+1 < len(s) && s[ip.pos+1] == '\n' {
				flushText(ip.pos)
				ip.nodes = append(ip.nodes, &inlineNode{kind: "br"})
				ip.pos += 2
				continue
			}
			if ip.pos+1 < len(s) && isASCIIPunct(s[ip.pos+1]) {
				flushText(ip.pos)
				ip.addText(string(s[ip.pos+1]))
				ip.pos += 2
				continue
			}
		case '`':
			n := 0
			for ip.pos+n < len(s) && s[ip.pos+n] == '`' {
				n++
			}
			// find closing run of same length
			j := ip.pos + n
			found := -1
			for j < len(s) {
				if s[j] == '`' {
					k := 0
					for j+k < len(s) && s[j+k] == '`' {
						k++
					}
					if k == n {
						found = j
						break
					}
					j += k
				} else {
					j++
				}
			}
			flushText(ip.pos)
			if found >= 0 {
				content := strings.ReplaceAll(s[ip.pos+n:found], "\n", " ")
				if len(content) >= 2 && content[0] == ' ' && content[len(content)-1] == ' ' && strings.Trim(content, " ") != "" {
					content = content[1 : len(content)-1]
				}
				ip.nodes = append(ip.nodes, &inlineNode{kind: "code", text: content})
				ip.pos = found + n
			} else {
				ip.addText(s[ip.pos : ip.pos+n])
				ip.pos += n
			}
			continue
		case '*', '_':
			flushText(ip.pos)
			n := 0
			for ip.pos+n < len(s) && s[ip.pos+n] == c {
				n++
			}
			before, _ := utf8.DecodeLastRuneInString(s[:ip.pos])
			if ip.pos == 0 {
				before = -1
			}
			after, _ := utf8.DecodeRuneInString(s[ip.pos+n:])
			if ip.pos+n >= len(s) {
				after = -1
			}
			leftFlanking := !isUnicodeWhitespace(after) && (!isPunct(after) || isUnicodeWhitespace(before) || isPunct(before))
			rightFlanking := !isUnicodeWhitespace(before) && (!isPunct(before) || isUnicodeWhitespace(after) || isPunct(after))
			var canOpen, canClose bool
			if c == '*' {
				canOpen = leftFlanking
				canClose = rightFlanking
			} else {
				canOpen = leftFlanking && (!rightFlanking || isPunct(before))
				canClose = rightFlanking && (!leftFlanking || isPunct(after))
			}
			ip.nodes = append(ip.nodes, &inlineNode{kind: "delim", text: s[ip.pos : ip.pos+n]})
			ip.delims = append(ip.delims, &delim{pos: len(ip.nodes) - 1, ch: c, count: n, origCount: n, canOpen: canOpen, canClose: canClose, active: true})
			ip.pos += n
			continue
		case '[':
			flushText(ip.pos)
			ip.nodes = append(ip.nodes, &inlineNode{kind: "text", text: "["})
			ip.brackets = append(ip.brackets, &bracket{nodeIdx: len(ip.nodes) - 1, active: true, delimLen: len(ip.delims)})
			ip.pos++
			continue
		case '!':
			if ip.pos+1 < len(s) && s[ip.pos+1] == '[' {
				flushText(ip.pos)
				ip.nodes = append(ip.nodes, &inlineNode{kind: "text", text: "!["})
				ip.brackets = append(ip.brackets, &bracket{nodeIdx: len(ip.nodes) - 1, image: true, active: true, delimLen: len(ip.delims)})
				ip.pos += 2
				continue
			}
		case ']':
			flushText(ip.pos)
			ip.pos++
			ip.closeBracket()
			continue
		case '<':
			flushText(ip.pos)
			rest := s[ip.pos:]
			if m := autolinkRe.FindStringSubmatch(rest); m != nil {
				ip.nodes = append(ip.nodes, &inlineNode{kind: "link", dest: m[1], children: []*inlineNode{{kind: "text", text: m[1]}}})
				ip.pos += len(m[0])
				continue
			}
			if m := emailAutolinkRe.FindStringSubmatch(rest); m != nil {
				ip.nodes = append(ip.nodes, &inlineNode{kind: "link", dest: "mailto:" + m[1], children: []*inlineNode{{kind: "text", text: m[1]}}})
				ip.pos += len(m[0])
				continue
			}
			if m := inlineHTMLRe.FindString(rest); m != "" {
				ip.nodes = append(ip.nodes, &inlineNode{kind: "html", text: m})
				ip.pos += len(m)
				continue
			}
			ip.addText("<")
			ip.pos++
			continue
		case '&':
			if m := entityRe.FindString(s[ip.pos:]); m != "" {
				flushText(ip.pos)
				ip.addText(decodeEntities(m))
				ip.pos += len(m)
				continue
			}
		case '\n':
			// hard break with trailing spaces?
			end := ip.pos
			spaces := 0
			for end > 0 && s[end-1] == ' ' {
				end--
				spaces++
			}
			if textStart >= 0 && end > textStart {
				ip.addText(s[textStart:end])
			} else if textStart >= 0 {
				// only spaces
			}
			textStart = -1
			if spaces >= 2 {
				ip.nodes = append(ip.nodes, &inlineNode{kind: "br"})
			} else {
				ip.nodes = append(ip.nodes, &inlineNode{kind: "softbreak"})
			}
			ip.pos++
			// skip leading spaces of next line
			for ip.pos < len(s) && s[ip.pos] == ' ' {
				ip.pos++
			}
			continue
		}
		if textStart < 0 {
			textStart = ip.pos
		}
		ip.pos++
	}
	flushText(len(s))
	// trailing spaces on final line are stripped by paragraph normalization
	if len(ip.nodes) > 0 {
		last := ip.nodes[len(ip.nodes)-1]
		if last.kind == "text" {
			last.text = strings.TrimRight(last.text, " ")
		}
	}
}

var linkDestTitleRe = regexp.MustCompile(`^\(\s*(<[^<>\n]*>|(?:[^\s()\\]|\\.|\((?:[^\s()\\]|\\.)*\))*)(?:\s+("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\((?:[^()\\]|\\.)*\)))?\s*\)`)

func (ip *inlineParser) closeBracket() {
	if len(ip.brackets) == 0 {
		ip.addText("]")
		return
	}
	br := ip.brackets[len(ip.brackets)-1]
	ip.brackets = ip.brackets[:len(ip.brackets)-1]
	if !br.active {
		ip.addText("]")
		return
	}
	s := ip.s
	var dest, title string
	matched := false
	consumed := 0
	rest := s[ip.pos:]
	if m := linkDestTitleRe.FindStringSubmatch(rest); m != nil {
		dest = m[1]
		if strings.HasPrefix(dest, "<") {
			dest = dest[1 : len(dest)-1]
		}
		if m[2] != "" {
			title = m[2][1 : len(m[2])-1]
		}
		dest = unescapeMd(dest)
		title = unescapeMd(title)
		matched = true
		consumed = len(m[0])
	} else {
		// reference link
		label := ""
		if m := regexp.MustCompile(`^\[((?:[^\]\\]|\\.){0,999})\]`).FindStringSubmatch(rest); m != nil && strings.TrimSpace(m[1]) != "" {
			label = m[1]
			consumed = len(m[0])
		} else {
			// collapsed/shortcut: use the bracket text
			var tb strings.Builder
			for _, n := range ip.nodes[br.nodeIdx+1:] {
				collectText(&tb, n)
			}
			label = tb.String()
			if m != nil {
				consumed = len(m[0])
			}
		}
		if ref, ok := ip.p.refs[normalizeLabel(label)]; ok {
			dest, title = ref.dest, ref.title
			matched = true
		}
	}
	if !matched {
		ip.addText("]")
		return
	}
	// build node
	children := append([]*inlineNode(nil), ip.nodes[br.nodeIdx+1:]...)
	// process emphasis within
	ip.processEmphasis(br.delimLen)
	children = append([]*inlineNode(nil), ip.nodes[br.nodeIdx+1:]...)
	kind := "link"
	if br.image {
		kind = "image"
	}
	node := &inlineNode{kind: kind, dest: dest, title: title, children: children}
	ip.nodes = append(ip.nodes[:br.nodeIdx], node)
	ip.delims = ip.delims[:br.delimLen]
	ip.pos += consumed
	if !br.image {
		for _, b := range ip.brackets {
			if !b.image {
				b.active = false
			}
		}
	}
}

func collectText(sb *strings.Builder, n *inlineNode) {
	switch n.kind {
	case "text", "delim", "code":
		sb.WriteString(n.text)
	default:
		for _, c := range n.children {
			collectText(sb, c)
		}
	}
}

// processEmphasis implements the delimiter stack algorithm for nodes after stackBottom.
func (ip *inlineParser) processEmphasis(stackBottom int) {
	// work on delimiters with index > stackBottom
	start := stackBottom + 1
	if start < 0 {
		start = 0
	}
	delims := ip.delims[start:]
	// map from node pointer to delim for lookups
	closerIdx := 0
	openersBottom := map[byte][3]int{}
	for _, c := range []byte{'*', '_'} {
		openersBottom[c] = [3]int{-1, -1, -1}
	}
	for closerIdx < len(delims) {
		closer := delims[closerIdx]
		if !closer.canClose || !closer.active || closer.count == 0 {
			closerIdx++
			continue
		}
		// look back for opener
		openerIdx := closerIdx - 1
		found := false
		ob := openersBottom[closer.ch][closer.origCount%3]
		for openerIdx > ob {
			opener := delims[openerIdx]
			if opener.active && opener.count > 0 && opener.ch == closer.ch && opener.canOpen {
				oddMatch := (closer.canOpen || opener.canClose) && closer.origCount%3 != 0 && (opener.origCount+closer.origCount)%3 == 0
				if !oddMatch {
					found = true
					break
				}
			}
			openerIdx--
		}
		if !found {
			b := openersBottom[closer.ch]
			b[closer.origCount%3] = closerIdx - 1
			openersBottom[closer.ch] = b
			if !closer.canOpen {
				closer.active = false
			}
			closerIdx++
			continue
		}
		opener := delims[openerIdx]
		use := 1
		if opener.count >= 2 && closer.count >= 2 {
			use = 2
		}
		opener.count -= use
		closer.count -= use
		openerNode := ip.nodes[opener.pos]
		closerNode := ip.nodes[closer.pos]
		openerNode.text = openerNode.text[:len(openerNode.text)-use]
		closerNode.text = closerNode.text[:len(closerNode.text)-use]
		kind := "em"
		if use == 2 {
			kind = "strong"
		}
		// nodes between opener and closer become children
		inner := append([]*inlineNode(nil), ip.nodes[opener.pos+1:closer.pos]...)
		node := &inlineNode{kind: kind, children: inner}
		// rebuild nodes
		newNodes := append([]*inlineNode(nil), ip.nodes[:opener.pos+1]...)
		newNodes = append(newNodes, node)
		newNodes = append(newNodes, ip.nodes[closer.pos:]...)
		shift := closer.pos - (opener.pos + 1) - 1 // removed count minus the added node
		ip.nodes = newNodes
		// deactivate delims between opener and closer and fix positions
		for i := openerIdx + 1; i < closerIdx; i++ {
			delims[i].active = false
		}
		for i := closerIdx; i < len(delims); i++ {
			delims[i].pos -= shift
		}
		for i := len(ip.delims) - len(delims) + closerIdx; i < len(ip.delims); i++ {
			_ = i
		}
		if opener.count == 0 {
			opener.active = false
		}
		if closer.count == 0 {
			closer.active = false
			closerIdx++
		}
	}
	// remove empty delimiter nodes
	var newNodes []*inlineNode
	for _, n := range ip.nodes {
		if n.kind == "delim" && n.text == "" {
			continue
		}
		newNodes = append(newNodes, n)
	}
	// positions no longer needed after final processing
	ip.nodes = newNodes
	if stackBottom < 0 {
		ip.delims = nil
	} else {
		ip.delims = ip.delims[:start]
	}
}
