// openParagraph returns the open paragraph that a new line would continue, if any.
func (p *mdParser) openParagraph(container *mdBlock, allMatched bool, startedNew bool) *mdBlock {
	if startedNew {
		return nil
	}
	if allMatched {
		if lc := p.lastChild(container); lc != nil && lc.open && lc.kind == "paragraph" {
			return lc
		}
		return nil
	}
	deep := p.deepestOpenLeaf(p.root)
	if deep != nil && deep.kind == "paragraph" {
		return deep
	}
	return nil
}

// setLastLineBlank marks a node and clears the flag on its ancestors.
func (p *mdParser) setLastLineBlank(b *mdBlock, blank bool) {
	b.lastLineBlank = blank
	for par := b.parent; par != nil; par = par.parent {
