new='''// addLine feeds one line to the block parser (cmark-style algorithm).
func (p *mdParser) addLine(line string) {
	p.lineNo++
	container := p.root
	rest := line
	allMatched := true
	// 1. match continuation markers of open containers
	for {
		child := p.lastChild(container)
		if child == nil || !child.open {
			break
		}
		switch child.kind {
		case "list":
			container = child
			continue
		case "quote":
			ind := indentOf(rest)
			if ind <= 3 && ind < len(rest) && rest[ind] == '>' {
				rest = rest[ind+1:]
				if strings.HasPrefix(rest, " ") {
					rest = rest[1:]
				}
				container = child
				continue
			}
			allMatched = false
		case "item":
			if isBlank(rest) {
				if len(child.children) == 0 && child.startLine != p.lineNo && child.startedBlank {
					allMatched = false
				} else {
					container = child
					continue
				}
			} else if indentOf(rest) >= child.indent {
				rest = rest[child.indent:]
				container = child
				continue
			} else {
				allMatched = false
			}
		default:
			// leaf
		}
		break
	}
	// 2. open leaf continuation (fenced / html / indented code)
	leaf := p.lastChild(container)
	if allMatched && leaf != nil && leaf.open && leaf.kind != "paragraph" && leaf.kind != "list" && leaf.kind != "quote" && leaf.kind != "item" {
		switch leaf.kind {
		case "fenced":
			ind := indentOf(rest)
			if ind <= 3 {
				t := strings.TrimRight(rest[ind:], " \\t")
				if strings.HasPrefix(t, leaf.fence) && strings.Trim(t, string(leaf.fence[0])) == "" {
					leaf.open = false
					p.setLastLineBlank(leaf, false)
					return
				}
			}
			strip := leaf.fenceInd
			if indentOf(rest) < strip {
				strip = indentOf(rest)
			}
			leaf.lines = append(leaf.lines, rest[strip:])
			p.setLastLineBlank(leaf, false)
			return
		case "html":
			leaf.lines = append(leaf.lines, rest)
			if htmlBlockEnds(leaf, rest) {
				leaf.open = false
			}
			p.setLastLineBlank(leaf, isBlank(rest))
			return
		case "code":
			if indentOf(rest) >= 4 {
				leaf.lines = append(leaf.lines, rest[4:])
				p.setLastLineBlank(leaf, false)
				return
			}
			if isBlank(rest) {
				leaf.lines = append(leaf.lines, "")
				p.setLastLineBlank(leaf, true)
				return
			}
			leaf.open = false
		}
	}
	// 3. new block starts
	startedNew := false
	for {
		ind := indentOf(rest)
		if ind >= 4 {
			break
		}
		t := rest[ind:]
		if strings.HasPrefix(t, ">") {
			p.closeUnmatched(container)
			q := &mdBlock{kind: "quote", open: true, startLine: p.lineNo}
			container.children = append(container.children, q)
			container = q
			rest = t[1:]
			if strings.HasPrefix(rest, " ") {
				rest = rest[1:]
			}
			startedNew = true
			allMatched = true
			continue
		}
		if m := atxRe.FindStringSubmatch(rest); m != nil {
			p.closeUnmatched(container)
			content := strings.TrimSpace(m[2])
			if i := strings.LastIndex(content, " #"); i >= 0 && strings.Trim(content[i+1:], "#") == "" {
				content = strings.TrimRight(content[:i], " \\t")
			} else if strings.Trim(content, "#") == "" {
				content = ""
			}
			h := &mdBlock{kind: "heading", level: len(m[1]), lines: []string{content}, startLine: p.lineNo}
			container.children = append(container.children, h)
			p.setLastLineBlank(h, false)
			return
		}
		if m := fenceRe.FindStringSubmatch(rest); m != nil {
			info := strings.TrimSpace(m[3])
			if !(m[2][0] == '`' && strings.Contains(info, "`")) {
				p.closeUnmatched(container)
				f := &mdBlock{kind: "fenced", open: true, fence: m[2], fenceInd: len(m[1]), info: info, startLine: p.lineNo}
				container.children = append(container.children, f)
				p.setLastLineBlank(f, false)
				return
			}
		}
		if htmlBlockStartRe.MatchString(rest) {
			kind := htmlBlockKind(rest)
			para := p.openParagraph(container, allMatched, startedNew)
			if !(kind == 7 && para != nil) {
				p.closeUnmatched(container)
				b := &mdBlock{kind: "html", open: true, level: kind, lines: []string{rest}, startLine: p.lineNo}
				container.children = append(container.children, b)
				if htmlBlockEnds(b, rest) {
					b.open = false
				}
				p.setLastLineBlank(b, false)
				return
			}
		}
		if para := p.openParagraph(container, allMatched, startedNew); para != nil && setextRe.MatchString(rest) {
			level := 2
			if strings.Contains(rest, "=") {
				level = 1
			}
			para.kind = "heading"
			para.level = level
			para.open = false
			para.lines = []string{strings.Join(para.lines, "\\n")}
			p.setLastLineBlank(para, false)
			return
		}
		if hrRe.MatchString(rest) {
			p.closeUnmatched(container)
			h := &mdBlock{kind: "hr", startLine: p.lineNo}
			container.children = append(container.children, h)
			p.setLastLineBlank(h, false)
			return
		}
		para := p.openParagraph(container, allMatched, startedNew)
		if m := bulletRe.FindStringSubmatch(rest); m != nil {
			if !(para != nil && isBlank(m[4])) {
				p.closeUnmatched(container)
				item, content := p.startListItem(container, false, 0, m[2][0], 0, len(m[1]), len(m[2]), m[3], m[4])
