				rest = content
				startedNew = true
				allMatched = true
				continue
			}
		}
		if m := orderedRe.FindStringSubmatch(rest); m != nil {
			start, _ := strconv.Atoi(m[2])
			if !(para != nil && (start != 1 || isBlank(m[5]))) {
				p.closeUnmatched(container)
				item, content := p.startListItem(container, true, start, 0, m[3][0], len(m[1]), len(m[2])+1, m[4], m[5])
				container = item
				rest = content
				startedNew = true
				allMatched = true
				continue
			}
		}
		break
	}
	// 4. remaining text
	blank := isBlank(rest)
	if blank {
		if para := p.openParagraph(container, true, false); para != nil {
			para.open = false
		}
		// the deepest matched container gets the blank mark
		target := container
		if lc := p.lastChild(container); lc != nil && lc.open && (lc.kind == "paragraph" || lc.kind == "code") {
			target = lc
		}
		lastLineBlank := !(target.kind == "quote" || target.kind == "heading" || target.kind == "hr" || target.kind == "fenced" || (target.kind == "item" && len(target.children) == 0 && target.startLine == p.lineNo))
