			target.startedBlank = true
		}
		p.setLastLineBlank(target, lastLineBlank)
		return
	}
	// lazy continuation
	if !allMatched && !startedNew {
		deep := p.deepestOpenLeaf(p.root)
		if deep != nil && deep.kind == "paragraph" {
			deep.lines = append(deep.lines, strings.TrimLeft(rest, " "))
			p.setLastLineBlank(deep, false)
			return
		}
	}
	p.closeUnmatched(container)
	leaf = p.lastChild(container)
	if indentOf(rest) >= 4 {
		if leaf != nil && leaf.open && leaf.kind == "paragraph" {
			leaf.lines = append(leaf.lines, strings.TrimLeft(rest, " "))
			p.setLastLineBlank(leaf, false)
			return
		}
		c := &mdBlock{kind: "code", open: true, lines: []string{rest[4:]}, startLine: p.lineNo}
		container.children = append(container.children, c)
		p.setLastLineBlank(c, false)
		return
	}
	if leaf != nil && leaf.open && leaf.kind == "paragraph" {
		leaf.lines = append(leaf.lines, strings.TrimLeft(rest, " "))
		p.setLastLineBlank(leaf, false)
		return
	}
	para := &mdBlock{kind: "paragraph", open: true, lines: []string{strings.TrimLeft(rest, " ")}, startLine: p.lineNo}
	container.children = append(container.children, para)
	p.setLastLineBlank(para, false)
