		}
		contentIndent = leading + markerLen + 1
	}
	last := p.lastChild(container)
	var list *mdBlock
	if last != nil && last.open && last.kind == "list" && last.ordered == ordered && last.bullet == bullet && last.delim == delim {
		list = last
	} else {
		list = &mdBlock{kind: "list", open: true, ordered: ordered, start: start, bullet: bullet, delim: delim, tight: true, startLine: p.lineNo}
		p.appendChild(container, list)
	}
	if li := p.lastChild(list); li != nil && li.open {
		p.closeAll(li)
	}
	item := &mdBlock{kind: "item", open: true, indent: contentIndent, startLine: p.lineNo}
	p.appendChild(list, item)
	return item, content
}

func (p *mdParser) appendChild(parent, child *mdBlock) {
	child.parent = parent
	parent.children = append(parent.children, child)
}

