			for len(lines) > 0 && isBlank(lines[len(lines)-1]) {
				lines = lines[:len(lines)-1]
			}
			cr(sb)
			sb.WriteString("<pre><code>" + mdEscape(strings.Join(lines, "\\n")+"\\n") + "</code></pre>\\n")
		case "fenced":
			cls := ""
			if b.info != "" {
				lang := strings.Fields(unescapeMd(b.info))[0]
				cls = ` class="language-` + mdEscape(lang) + `"`
			}
			content := ""
