	if st.IsDir() {
		if !strings.HasSuffix(href, "/") {
			href += "/"
		}
		if !strings.HasSuffix(req.RawPath, "/") {
			r.SetHeader("content-location", href)
		}
	}
	var sb strings.Builder
	sb.WriteString(`<?xml version="1.0" encoding="utf-8"?><D:multistatus xmlns:D="DAV:"`)
	if mode == "propname" {
		sb.WriteString(` xmlns:A="http://apache.org/dav/props/"`)
	}
	sb.WriteString(`>`)
	sb.WriteString(davResponse(href, diskPath, st, mode, requested))
	if st.IsDir() && depth == "1" {
		f, err := os.Open(diskPath)
		if err == nil {
			names, _ := f.Readdirnames(-1)
			f.Close()
			for _, name := range names {
				if !c.ShowHidden && strings.HasPrefix(name, ".") {
					continue
				}
				full := filepath.Join(diskPath, name)
				lst, err := os.Lstat(full)
				if err != nil {
					continue
				}
				if lst.Mode()&os.ModeSymlink != 0 {
					if c.NoSymlinks {
						continue
					}
				}
				cst, err := os.Stat(full)
				if err != nil {
					continue
				}
				childHref := href + urlEncodePath(name)
				if cst.IsDir() {
					childHref += "/"
				}
				sb.WriteString(davResponse(childHref, full, cst, mode, requested))
			}
		}
	}
	sb.WriteString(`</D:multistatus>`)
	out := sb.String()
	r.Stream = func(w io.Writer) error {
		_, err := io.WriteString(w, out)
		return err
	}
	r.logSize = int64(len(out))
	return r
}

var propfindPropRe = regexp.MustCompile(`<(?:([A-Za-z0-9_.-]+):)?([A-Za-z0-9_.-]+)\s*/?>`)

// parsePropfindBody returns the mode (allprop, propname, prop) and requested props.
func parsePropfindBody(body string) (string, []davProp) {
	body = strings.TrimSpace(body)
	if body == "" {
		return "allprop", nil
	}
	lower := strings.ToLower(body)
	if strings.Contains(lower, "propname") {
		return "propname", nil
	}
	if strings.Contains(lower, "allprop") {
		return "allprop", nil
	}
	i := strings.Index(lower, ":prop>")
	if i < 0 {
		i = strings.Index(lower, "<prop>")
		if i < 0 {
			return "allprop", nil
		}
	}
	rest := body[i:]
	if j := strings.IndexByte(rest, '>'); j >= 0 {
		rest = rest[j+1:]
	}
	if j := strings.Index(strings.ToLower(rest), "prop>"); j >= 0 {
		// find closing </X:prop>
		k := strings.LastIndex(strings.ToLower(rest), "</")
		if k >= 0 {
			rest = rest[:k]
		}
	}
	var props []davProp
	for _, m := range propfindPropRe.FindAllStringSubmatch(rest, -1) {
		props = append(props, davProp{m[1], m[2]})
	}
	return "prop", props
}

func davPropValue(name string, path string, st os.FileInfo) (string, bool) {
	switch name {
	case "creationdate":
		return fileBirthTime(path, st).UTC().Format("2006-01-02T15:04:05Z"), true
	case "getcontentlength":
		if st.IsDir() {
			return "", false
		}
		return fmt.Sprintf("%d", st.Size()), true
	case "getcontenttype":
		if st.IsDir() {
			return "httpd/unix-directory", true
		}
		return guessMime(filepath.Base(path)), true
	case "getetag":
		var ino uint64
		mt := st.ModTime()
		if sys, ok := st.Sys().(*syscall.Stat_t); ok {
			ino = sys.Ino
			mt = time.Unix(sys.Mtim.Sec, sys.Mtim.Nsec)
		}
		micros := mt.UnixNano() / 1000
		if st.IsDir() {
			return fmt.Sprintf("%x-%x", ino, micros), true
		}
		return fmt.Sprintf("%x-%x-%x", ino, st.Size(), micros), true
	case "getlastmodified":
		return httpDate(st.ModTime()), true
	case "lockdiscovery", "supportedlock":
		return "", true
	case "resourcetype":
		if st.IsDir() {
			return "<D:collection></D:collection>", true
		}
		return "", true
	}
	return "", false
}

func davResponse(href string, path string, st os.FileInfo, mode string, requested []davProp) string {
	var sb strings.Builder
	sb.WriteString(`<D:response><D:href>` + htmlEscape(href) + `</D:href>`)
	switch mode {
	case "propname":
		sb.WriteString(`<D:propstat><D:prop>`)
		for _, n := range davAllProps {
			if _, ok := davPropValue(n, path, st); ok {
				sb.WriteString(`<D:` + n + `></D:` + n + `>`)
			}
		}
		sb.WriteString(`<A:executable></A:executable>`)
		sb.WriteString(`</D:prop><D:status>HTTP/1.1 200 OK</D:status></D:propstat>`)
	case "prop":
		var found, missing []string
		for _, p := range requested {
			if v, ok := davPropValue(p.name, path, st); ok && (p.ns == "" || true) {
				found = append(found, `<D:`+p.name+`>`+v+`</D:`+p.name+`>`)
			} else {
				missing = append(missing, `<D:`+p.name+`></D:`+p.name+`>`)
			}
		}
		if len(found) > 0 {
			sb.WriteString(`<D:propstat><D:prop>` + strings.Join(found, "") + `</D:prop><D:status>HTTP/1.1 200 OK</D:status></D:propstat>`)
		}
		if len(missing) > 0 {
			sb.WriteString(`<D:propstat><D:prop>` + strings.Join(missing, "") + `</D:prop><D:status>HTTP/1.1 404 Not Found</D:status></D:propstat>`)
		}
	default:
		sb.WriteString(`<D:propstat><D:prop>`)
		for _, n := range davAllProps {
			if v, ok := davPropValue(n, path, st); ok {
				sb.WriteString(`<D:` + n + `>` + v + `</D:` + n + `>`)
			}
		}
		sb.WriteString(`</D:prop><D:status>HTTP/1.1 200 OK</D:status></D:propstat>`)
	}
	sb.WriteString(`</D:response>`)
	return sb.String()
}
