		"-adj":  func(m *qrMatrix) int { return -adjVariant(m, false) },
		"-blk":  func(m *qrMatrix) int { return -blockVariant(m, false) },
		"-fin6": func(m *qrMatrix) int { return -finderV(m, 6) },
		"iso":   func(m *qrMatrix) int { return adjVariant(m, false) + blockVariant(m, false) + finderV(m, 6) + balanceV(m, 3) },
		"-iso":  func(m *qrMatrix) int { return -(adjVariant(m, false) + blockVariant(m, false) + finderV(m, 6) + balanceV(m, 3)) },
	}
	for name, f := range rules {
		hist := map[int]int{}
		for _, p := range pres {
			var scores [8]int
			for mask := 0; mask < 8; mask++ {
				scores[mask] = f(p.mats[mask])
			}
			rank := 0
			for mask := 0; mask < 8; mask++ {
				if scores[mask] < scores[p.want] {
					rank++
				}
			}
			hist[rank]++
		}
		fmt.Printf("%-6s rank0=%2d hist=%v\n", name, hist[0], hist)
	}
}
EOF
