package main

import (
	"fmt"
	"testing"
)

func lineRuns(m *qrMatrix, horiz bool) (adj int, runs5 int) {
	n := m.size
	for i := 0; i < n; i++ {
		run := 1
		last := -1
		for j := 0; j <= n; j++ {
			color := -2
			if j < n {
				if horiz {
					color = b2i(m.get(j, i))
				} else {
					color = b2i(m.get(i, j))
				}
			}
			if color == last {
				run++
			} else {
				if run >= 5 {
					adj += run - 2
					runs5++
				}
				last = color
				run = 1
			}
		}
	}
	return
}

func features(m *qrMatrix) []float64 {
	ar, r5r := lineRuns(m, true)
	ac, r5c := lineRuns(m, false)
	dark := 0
	for _, d := range m.modules {
		if d {
			dark++
		}
	}
	total := len(m.modules)
	pct := float64(dark) * 100 / float64(total)
	dev := pct - 50
	if dev < 0 {
		dev = -dev
	}
	return []float64{
		float64(ar), float64(ac), float64(r5r), float64(r5c),
		float64(blockVariant(m, false)),
		float64(finderV(m, 0)), float64(finderV(m, 1)), float64(finderV(m, 2)), float64(finderV(m, 4)), float64(finderV(m, 6)),
		float64(balanceV(m, 0)), float64(balanceV(m, 3)), dev, float64(dark),
		float64(adjVariant(m, true)), float64(blockVariant(m, true)),
	}
}

func TestQRPerceptron(t *testing.T) {
	cases := loadSamples()
	type sample struct {
		feats [8][]float64
		want  int
	}
	var samples []sample
	for _, c := range cases {
		version, data := qrEncode([]byte(c.url))
		cw := qrCodewords(version, data)
		n := version*4 + 17
		base := newMatrix(n)
		base.drawFunctionPatterns(version)
		base.drawData(cw)
		var s sample
		s.want = c.want
		for mask := 0; mask < 8; mask++ {
			s.feats[mask] = features(buildModeMatrix(base, mask, 1))
		}
		samples = append(samples, s)
	}
	nf := len(samples[0].feats[0])
	w := make([]float64, nf)
	for i := range w {
		w[i] = 1
	}
	for iter := 0; iter < 20000; iter++ {
		violations := 0
		for _, s := range samples {
			fc := s.feats[s.want]
			for m := 0; m < 8; m++ {
				if m == s.want {
					continue
				}
				// want score(c) < score(m): w·(fm - fc) > 0
				dot := 0.0
				for k := 0; k < nf; k++ {
					dot += w[k] * (s.feats[m][k] - fc[k])
				}
				if dot <= 0 {
					violations++
					for k := 0; k < nf; k++ {
						w[k] += 0.01 * (s.feats[m][k] - fc[k])
					}
				}
			}
		}
		if violations == 0 {
			fmt.Println("separable! weights:", w)
			return
		}
		if iter%5000 == 0 {
			fmt.Println("iter", iter, "violations", violations)
		}
	}
	fmt.Println("not separable; final w", w)
}
EOF
export PATH=$PATH:/usr/local/go/bin GOTOOLCHAIN=local; go test -v -run 'TestQRPerceptron' . 2>&1 | tail -6"}

